INSERT INTO rebalance_input (id, old_options, new_options) VALUES
  ('ca_121', $opt$[{"text":"Transitional living for released inmates","isCorrect":true,"rationale":"Halfway houses provide transitional housing for inmates preparing for release.","is_correct":true},{"text":"Secure housing for inmates awaiting trial","is_correct":false,"rationale":"Detainees awaiting trial are held in jails. Halfway houses serve offenders who are re-entering the community."},{"text":"Temporary shelter for victims of abuse","is_correct":false,"rationale":"That describes a crisis or women's shelter. Halfway houses house offenders returning to society."},{"text":"Diagnostic units for newly committed inmates","is_correct":false,"rationale":"New inmates go to the reception and diagnostic center. Halfway houses come at the end of the sentence, before full release."}]$opt$::jsonb, $opt$[{"text":"Transitional living for released inmates","isCorrect":true,"rationale":"Halfway houses provide transitional housing for inmates preparing for release.","is_correct":true},{"text":"Maximum security","isCorrect":false,"rationale":"'Maximum security' is incorrect. The correct answer is 'Transitional living for released inmates'. Halfway houses provide transitional housing for inmates preparing for release. Review: Community-Based Corrections.","is_correct":false},{"text":"Death row housing","isCorrect":false,"rationale":"'Death row housing' is incorrect. The correct answer is 'Transitional living for released inmates'. Halfway houses provide transitional housing for inmates preparing for release. Review: Community-Based Corrections.","is_correct":false},{"text":"Juvenile detention","isCorrect":false,"rationale":"'Juvenile detention' is incorrect. The correct answer is 'Transitional living for released inmates'. Halfway houses provide transitional housing for inmates preparing for release. Review: Community-Based Corrections.","is_correct":false}]$opt$::jsonb),
  ('ca_027', $opt$[{"text":"Assess and classify new inmates","isCorrect":true,"rationale":"Reception and diagnostic centers assess new inmates for proper classification and placement.","is_correct":true},{"text":"Prepare inmates for their release","is_correct":false,"rationale":"Pre-release programs do that near the end of the sentence. The RDC handles inmates at the start, on admission."},{"text":"Hold inmates under disciplinary penalty","is_correct":false,"rationale":"That is disciplinary segregation. The RDC studies and classifies newly committed inmates."},{"text":"Process visitors and inmate mail","is_correct":false,"rationale":"Visitation and mail are handled by custodial staff. The RDC exists to assess and classify new inmates."}]$opt$::jsonb, $opt$[{"text":"Assess and classify new inmates","isCorrect":true,"rationale":"Reception and diagnostic centers assess new inmates for proper classification and placement.","is_correct":true},{"text":"Release inmates","isCorrect":false,"rationale":"'Release inmates' is incorrect. The correct answer is 'Assess and classify new inmates'. Reception and diagnostic centers assess new inmates for proper classification and placement. Review: Inmate Classification.","is_correct":false},{"text":"Execute sentences","isCorrect":false,"rationale":"'Execute sentences' is incorrect. The correct answer is 'Assess and classify new inmates'. Reception and diagnostic centers assess new inmates for proper classification and placement. Review: Inmate Classification.","is_correct":false},{"text":"Train guards","isCorrect":false,"rationale":"'Train guards' is incorrect. The correct answer is 'Assess and classify new inmates'. Reception and diagnostic centers assess new inmates for proper classification and placement. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('ca_028', $opt$[{"text":"Crime, sentence, behavior, security risk","isCorrect":true,"rationale":"Classification considers crime committed, length of sentence, behavior, and security risk.","is_correct":true},{"text":"Religion, hometown, and family background","is_correct":false,"rationale":"These are not classification criteria; classifying by religion or origin would be discriminatory. Classification looks at the offense, sentence, conduct and risk."},{"text":"Age, gender, and educational attainment only","is_correct":false,"rationale":"These may affect housing or programs, but classification rests on the crime, sentence, behavior and security risk."},{"text":"Physical strength and work skills","is_correct":false,"rationale":"Skills may matter for work assignments, not for classification, which weighs the crime, sentence, behavior and risk."}]$opt$::jsonb, $opt$[{"text":"Crime, sentence, behavior, security risk","isCorrect":true,"rationale":"Classification considers crime committed, length of sentence, behavior, and security risk.","is_correct":true},{"text":"Height only","isCorrect":false,"rationale":"'Height only' is incorrect. The correct answer is 'Crime, sentence, behavior, security risk'. Classification considers crime committed, length of sentence, behavior, and security risk. Review: Inmate Classification.","is_correct":false},{"text":"Weight only","isCorrect":false,"rationale":"'Weight only' is incorrect. The correct answer is 'Crime, sentence, behavior, security risk'. Classification considers crime committed, length of sentence, behavior, and security risk. Review: Inmate Classification.","is_correct":false},{"text":"Age only","isCorrect":false,"rationale":"'Age only' is incorrect. The correct answer is 'Crime, sentence, behavior, security risk'. Classification considers crime committed, length of sentence, behavior, and security risk. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('ca_053', $opt$[{"text":"For most dangerous inmates","isCorrect":true,"rationale":"Maximum security is for the most dangerous inmates requiring highest supervision.","is_correct":true},{"text":"For inmates with short sentences","is_correct":false,"rationale":"Short sentences usually point to minimum security. Maximum security is for the most dangerous inmates."},{"text":"For inmates nearing their release","is_correct":false,"rationale":"Inmates close to release are usually moved down to minimum security. Maximum security is for the highest-risk inmates."},{"text":"For first-time offenders","is_correct":false,"rationale":"Being a first offender does not make an inmate high-risk. Maximum security is for the most dangerous inmates."}]$opt$::jsonb, $opt$[{"text":"For most dangerous inmates","isCorrect":true,"rationale":"Maximum security is for the most dangerous inmates requiring highest supervision.","is_correct":true},{"text":"For all inmates","isCorrect":false,"rationale":"'For all inmates' is incorrect. The correct answer is 'For most dangerous inmates'. Maximum security is for the most dangerous inmates requiring highest supervision. Review: Inmate Classification.","is_correct":false},{"text":"For first offenders","isCorrect":false,"rationale":"'For first offenders' is incorrect. The correct answer is 'For most dangerous inmates'. Maximum security is for the most dangerous inmates requiring highest supervision. Review: Inmate Classification.","is_correct":false},{"text":"For minor offenses","isCorrect":false,"rationale":"'For minor offenses' is incorrect. The correct answer is 'For most dangerous inmates'. Maximum security is for the most dangerous inmates requiring highest supervision. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('ca_054', $opt$[{"text":"For low-risk inmates","isCorrect":true,"rationale":"Minimum security is for low-risk inmates who need minimal supervision.","is_correct":true},{"text":"For high-risk inmates","is_correct":false,"rationale":"High-risk inmates go to maximum security. Minimum security is for low-risk inmates."},{"text":"For inmates serving life terms","is_correct":false,"rationale":"Inmates serving life terms are classified maximum security, not minimum."},{"text":"For newly arrived inmates","is_correct":false,"rationale":"New arrivals first go through reception and diagnosis before any security level is assigned."}]$opt$::jsonb, $opt$[{"text":"For low-risk inmates","isCorrect":true,"rationale":"Minimum security is for low-risk inmates who need minimal supervision.","is_correct":true},{"text":"For dangerous inmates","isCorrect":false,"rationale":"'For dangerous inmates' is incorrect. The correct answer is 'For low-risk inmates'. Minimum security is for low-risk inmates who need minimal supervision. Review: Inmate Classification.","is_correct":false},{"text":"For death row","isCorrect":false,"rationale":"'For death row' is incorrect. The correct answer is 'For low-risk inmates'. Minimum security is for low-risk inmates who need minimal supervision. Review: Inmate Classification.","is_correct":false},{"text":"No classification","isCorrect":false,"rationale":"'No classification' is incorrect. The correct answer is 'For low-risk inmates'. Minimum security is for low-risk inmates who need minimal supervision. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('ca_084', $opt$[{"text":"Crime severity, escape risk, behavior","isCorrect":true,"rationale":"Classification considers offense, escape risk, and institutional behavior.","is_correct":true},{"text":"Age, height, and physical build","is_correct":false,"rationale":"Physical traits do not decide the security level; the offense, escape risk and conduct do."},{"text":"Family income and educational level","is_correct":false,"rationale":"Socioeconomic status is not a basis for security classification."},{"text":"Preference of the inmate and family","is_correct":false,"rationale":"Inmates do not choose their security level; it is assessed from crime severity, escape risk and behavior."}]$opt$::jsonb, $opt$[{"text":"Crime severity, escape risk, behavior","isCorrect":true,"rationale":"Classification considers offense, escape risk, and institutional behavior.","is_correct":true},{"text":"Age only","isCorrect":false,"rationale":"'Age only' is incorrect. The correct answer is 'Crime severity, escape risk, behavior'. Classification considers offense, escape risk, and institutional behavior. Review: Inmate Classification.","is_correct":false},{"text":"Gender only","isCorrect":false,"rationale":"'Gender only' is incorrect. The correct answer is 'Crime severity, escape risk, behavior'. Classification considers offense, escape risk, and institutional behavior. Review: Inmate Classification.","is_correct":false},{"text":"Education level","isCorrect":false,"rationale":"'Education level' is incorrect. The correct answer is 'Crime severity, escape risk, behavior'. Classification considers offense, escape risk, and institutional behavior. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('ca_092', $opt$[{"text":"Using standardized criteria for placement","isCorrect":true,"rationale":"Objective classification uses standardized tools for fair placement.","is_correct":true},{"text":"Relying on the warden's personal judgment","is_correct":false,"rationale":"That is subjective classification. Objective classification uses standardized, scored criteria."},{"text":"Placing inmates in order of arrival","is_correct":false,"rationale":"Order of arrival is not a classification method; objective systems score each inmate on set criteria."},{"text":"Letting inmates choose their own housing unit","is_correct":false,"rationale":"Placement is decided by the institution using standardized criteria, not by the inmates."}]$opt$::jsonb, $opt$[{"text":"Using standardized criteria for placement","isCorrect":true,"rationale":"Objective classification uses standardized tools for fair placement.","is_correct":true},{"text":"Subjective judgment","isCorrect":false,"rationale":"'Subjective judgment' is incorrect. The correct answer is 'Using standardized criteria for placement'. Objective classification uses standardized tools for fair placement. Review: Inmate Classification.","is_correct":false},{"text":"Random assignment","isCorrect":false,"rationale":"'Random assignment' is incorrect. The correct answer is 'Using standardized criteria for placement'. Objective classification uses standardized tools for fair placement. Review: Inmate Classification.","is_correct":false},{"text":"Alphabetical order","isCorrect":false,"rationale":"'Alphabetical order' is incorrect. The correct answer is 'Using standardized criteria for placement'. Objective classification uses standardized tools for fair placement. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('corr_136', $opt$[{"text":"Categorizing inmates by risk and needs","isCorrect":true,"rationale":"Classification assesses inmates to determine appropriate security level and program needs.","is_correct":true},{"text":"Assigning inmates to cells in order of arrival","is_correct":false,"rationale":"Order of arrival ignores risk and needs, which are the basis of classification."},{"text":"Grouping inmates by home region","is_correct":false,"rationale":"Where an inmate comes from is not a classification basis; inmates are classified by risk and needs."},{"text":"Ranking inmates by their length of stay","is_correct":false,"rationale":"Time served alone does not classify inmates; classification weighs risk and needs."}]$opt$::jsonb, $opt$[{"text":"Categorizing inmates by risk and needs","isCorrect":true,"rationale":"Classification assesses inmates to determine appropriate security level and program needs.","is_correct":true},{"text":"Random assignment","isCorrect":false,"rationale":"'Random assignment' is incorrect. The correct answer is 'Categorizing inmates by risk and needs'. Classification assesses inmates to determine appropriate security level and program needs. Review: Inmate Classification.","is_correct":false},{"text":"Alphabetical sorting","isCorrect":false,"rationale":"'Alphabetical sorting' is incorrect. The correct answer is 'Categorizing inmates by risk and needs'. Classification assesses inmates to determine appropriate security level and program needs. Review: Inmate Classification.","is_correct":false},{"text":"Age grouping","isCorrect":false,"rationale":"'Age grouping' is incorrect. The correct answer is 'Categorizing inmates by risk and needs'. Classification assesses inmates to determine appropriate security level and program needs. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('qb_ca_007', $opt$[{"text":"Age, health, and physical condition","is_correct":false,"rationale":"Health and age may affect housing or medical care, but security classification rests on the crime, sentence and escape risk."},{"text":"Crime committed, sentence, and escape risk","isCorrect":true,"rationale":"Security classification considers the nature of the offense, length of sentence, and potential escape risk.","is_correct":true},{"text":"Educational attainment and work skills","is_correct":false,"rationale":"These guide program and work assignments, not security classification."},{"text":"Financial status and family connections","is_correct":false,"rationale":"Wealth or connections must never decide the security level; it is based on the crime, sentence and escape risk."}]$opt$::jsonb, $opt$[{"text":"Age only","isCorrect":false,"rationale":"'Age only' is incorrect. The correct answer is 'Crime committed, sentence, and escape risk'. Security classification considers the nature of the offense, length of sentence, and potential escape risk. Review: Inmate Classification.","is_correct":false},{"text":"Crime committed, sentence, and escape risk","isCorrect":true,"rationale":"Security classification considers the nature of the offense, length of sentence, and potential escape risk.","is_correct":true},{"text":"Educational attainment","isCorrect":false,"rationale":"'Educational attainment' is incorrect. The correct answer is 'Crime committed, sentence, and escape risk'. Security classification considers the nature of the offense, length of sentence, and potential escape risk. Review: Inmate Classification.","is_correct":false},{"text":"Financial status","isCorrect":false,"rationale":"'Financial status' is incorrect. The correct answer is 'Crime committed, sentence, and escape risk'. Security classification considers the nature of the offense, length of sentence, and potential escape risk. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb),
  ('ca_009', $opt$[{"text":"Parole and Probation Administration","isCorrect":true,"rationale":"The Parole and Probation Administration supervises probationers and parolees in the community.","is_correct":true},{"text":"Bureau of Jail Management and Penology","is_correct":false,"rationale":"BJMP runs city, district and municipal jails for detainees and short-term prisoners; it does not supervise probationers."},{"text":"Bureau of Corrections","is_correct":false,"rationale":"BuCor manages the national penitentiaries for inmates serving long sentences, not probationers in the community."},{"text":"Board of Pardons and Parole","is_correct":false,"rationale":"The Board grants parole and recommends clemency; field supervision of probationers is done by the PPA."}]$opt$::jsonb, $opt$[{"text":"Parole and Probation Administration","isCorrect":true,"rationale":"The Parole and Probation Administration supervises probationers and parolees in the community.","is_correct":true},{"text":"BUCOR","isCorrect":false,"rationale":"'BUCOR' is incorrect. The correct answer is 'Parole and Probation Administration'. The Parole and Probation Administration supervises probationers and parolees in the community. Review: Non-Institutional Corrections.","is_correct":false},{"text":"BJMP","isCorrect":false,"rationale":"'BJMP' is incorrect. The correct answer is 'Parole and Probation Administration'. The Parole and Probation Administration supervises probationers and parolees in the community. Review: Non-Institutional Corrections.","is_correct":false},{"text":"DSWD","isCorrect":false,"rationale":"'DSWD' is incorrect. The correct answer is 'Parole and Probation Administration'. The Parole and Probation Administration supervises probationers and parolees in the community. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb),
  ('ca_017', $opt$[{"text":"The trial court","isCorrect":true,"rationale":"The trial court that convicted the offender has the power to grant probation.","is_correct":true},{"text":"The Court of Appeals","is_correct":false,"rationale":"Under PD 968 the application is filed with and decided by the trial court that convicted the offender, not an appellate court."},{"text":"The Board of Pardons and Parole","is_correct":false,"rationale":"The Board handles parole and clemency. Probation is granted by the trial court."},{"text":"The President","is_correct":false,"rationale":"The President grants pardon and other clemency, not probation, which is a judicial grant."}]$opt$::jsonb, $opt$[{"text":"The trial court","isCorrect":true,"rationale":"The trial court that convicted the offender has the power to grant probation.","is_correct":true},{"text":"The President","isCorrect":false,"rationale":"'The President' is incorrect. The correct answer is 'The trial court'. The trial court that convicted the offender has the power to grant probation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"The PNP","isCorrect":false,"rationale":"'The PNP' is incorrect. The correct answer is 'The trial court'. The trial court that convicted the offender has the power to grant probation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"The BJMP","isCorrect":false,"rationale":"'The BJMP' is incorrect. The correct answer is 'The trial court'. The trial court that convicted the offender has the power to grant probation. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb),
  ('ca_018', $opt$[{"text":"Those sentenced to more than 6 years","isCorrect":true,"rationale":"Offenders sentenced to more than 6 years imprisonment are not eligible for probation.","is_correct":true},{"text":"Those convicted for the first time","is_correct":false,"rationale":"First offenders are the main beneficiaries of probation; being a first-time offender does not disqualify anyone."},{"text":"Those sentenced to a fine only","is_correct":false,"rationale":"PD 968 allows probation whether the sentence is imprisonment or a fine only, so a fine does not disqualify."},{"text":"Those sentenced to exactly 6 years","is_correct":false,"rationale":"The bar is a maximum term of MORE than six years. A sentence of exactly six years is still within the limit."}]$opt$::jsonb, $opt$[{"text":"Those sentenced to more than 6 years","isCorrect":true,"rationale":"Offenders sentenced to more than 6 years imprisonment are not eligible for probation.","is_correct":true},{"text":"All crimes","isCorrect":false,"rationale":"'All crimes' is incorrect. The correct answer is 'Those sentenced to more than 6 years'. Offenders sentenced to more than 6 years imprisonment are not eligible for probation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Minor crimes only","isCorrect":false,"rationale":"'Minor crimes only' is incorrect. The correct answer is 'Those sentenced to more than 6 years'. Offenders sentenced to more than 6 years imprisonment are not eligible for probation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"First offenses","isCorrect":false,"rationale":"'First offenses' is incorrect. The correct answer is 'Those sentenced to more than 6 years'. Offenders sentenced to more than 6 years imprisonment are not eligible for probation. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb),
  ('ca_048', $opt$[{"text":"Rules probationer must follow","isCorrect":true,"rationale":"Probation conditions are rules the probationer must follow during supervision.","is_correct":true},{"text":"Rules for the parole board's hearings","is_correct":false,"rationale":"Those are procedural rules of the Board. Conditions of probation bind the probationer."},{"text":"Requirements to file an application","is_correct":false,"rationale":"Those must be met before probation is granted. Conditions are the rules the probationer must keep while on probation."},{"text":"Penalties for the probation officer","is_correct":false,"rationale":"Conditions apply to the probationer, not to the officer who supervises them."}]$opt$::jsonb, $opt$[{"text":"Rules probationer must follow","isCorrect":true,"rationale":"Probation conditions are rules the probationer must follow during supervision.","is_correct":true},{"text":"No conditions","isCorrect":false,"rationale":"'No conditions' is incorrect. The correct answer is 'Rules probationer must follow'. Probation conditions are rules the probationer must follow during supervision. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Prison rules","isCorrect":false,"rationale":"'Prison rules' is incorrect. The correct answer is 'Rules probationer must follow'. Probation conditions are rules the probationer must follow during supervision. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Parole rules","isCorrect":false,"rationale":"'Parole rules' is incorrect. The correct answer is 'Rules probationer must follow'. Probation conditions are rules the probationer must follow during supervision. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb),
  ('ca_049', $opt$[{"text":"Board of Pardons and Parole","isCorrect":true,"rationale":"The Board of Pardons and Parole grants parole to qualified prisoners.","is_correct":true},{"text":"Parole and Probation Administration","is_correct":false,"rationale":"The PPA supervises parolees after release, but parole itself is granted by the Board of Pardons and Parole."},{"text":"The sentencing trial court","is_correct":false,"rationale":"Courts grant probation, not parole. Parole is granted by the Board of Pardons and Parole."},{"text":"Bureau of Corrections","is_correct":false,"rationale":"BuCor holds the inmate and forwards records, but it does not grant parole."}]$opt$::jsonb, $opt$[{"text":"Board of Pardons and Parole","isCorrect":true,"rationale":"The Board of Pardons and Parole grants parole to qualified prisoners.","is_correct":true},{"text":"Judge","isCorrect":false,"rationale":"'Judge' is incorrect. The correct answer is 'Board of Pardons and Parole'. The Board of Pardons and Parole grants parole to qualified prisoners. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Prosecutor","isCorrect":false,"rationale":"'Prosecutor' is incorrect. The correct answer is 'Board of Pardons and Parole'. The Board of Pardons and Parole grants parole to qualified prisoners. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Police","isCorrect":false,"rationale":"'Police' is incorrect. The correct answer is 'Board of Pardons and Parole'. The Board of Pardons and Parole grants parole to qualified prisoners. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb),
  ('ca_022', $opt$[{"text":"Reduction of sentence","isCorrect":true,"rationale":"Commutation is the reduction of a sentence to a lesser penalty.","is_correct":true},{"text":"Postponement of sentence","is_correct":false,"rationale":"That is a reprieve. Commutation reduces the sentence, for example from death to life imprisonment."},{"text":"Forgiveness of the offense","is_correct":false,"rationale":"That is pardon. Commutation keeps the conviction but lowers the penalty."},{"text":"Release on parole","is_correct":false,"rationale":"Parole is release under supervision. Commutation is an act of clemency that reduces the sentence."}]$opt$::jsonb, $opt$[{"text":"Reduction of sentence","isCorrect":true,"rationale":"Commutation is the reduction of a sentence to a lesser penalty.","is_correct":true},{"text":"Full pardon","isCorrect":false,"rationale":"'Full pardon' is incorrect. The correct answer is 'Reduction of sentence'. Commutation is the reduction of a sentence to a lesser penalty. Review: Pardon and Amnesty.","is_correct":false},{"text":"Amnesty","isCorrect":false,"rationale":"'Amnesty' is incorrect. The correct answer is 'Reduction of sentence'. Commutation is the reduction of a sentence to a lesser penalty. Review: Pardon and Amnesty.","is_correct":false},{"text":"Probation","isCorrect":false,"rationale":"'Probation' is incorrect. The correct answer is 'Reduction of sentence'. Commutation is the reduction of a sentence to a lesser penalty. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb),
  ('ca_023', $opt$[{"text":"Temporary postponement of sentence","isCorrect":true,"rationale":"Reprieve is a temporary postponement or suspension of the execution of a sentence.","is_correct":true},{"text":"Permanent reduction of the sentence","is_correct":false,"rationale":"That is commutation. A reprieve only delays the execution of the sentence."},{"text":"Forgiveness that restores all rights","is_correct":false,"rationale":"That describes an absolute pardon. A reprieve only postpones the sentence."},{"text":"Early release under supervision","is_correct":false,"rationale":"That is parole. A reprieve is a temporary stay of the sentence."}]$opt$::jsonb, $opt$[{"text":"Temporary postponement of sentence","isCorrect":true,"rationale":"Reprieve is a temporary postponement or suspension of the execution of a sentence.","is_correct":true},{"text":"Full pardon","isCorrect":false,"rationale":"'Full pardon' is incorrect. The correct answer is 'Temporary postponement of sentence'. Reprieve is a temporary postponement or suspension of the execution of a sentence. Review: Pardon and Amnesty.","is_correct":false},{"text":"Reduced sentence","isCorrect":false,"rationale":"'Reduced sentence' is incorrect. The correct answer is 'Temporary postponement of sentence'. Reprieve is a temporary postponement or suspension of the execution of a sentence. Review: Pardon and Amnesty.","is_correct":false},{"text":"Probation","isCorrect":false,"rationale":"'Probation' is incorrect. The correct answer is 'Temporary postponement of sentence'. Reprieve is a temporary postponement or suspension of the execution of a sentence. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb),
  ('ca_050', $opt$[{"text":"Reducing the penalty imposed","isCorrect":true,"rationale":"Commutation reduces the penalty imposed without forgiving the offense.","is_correct":true},{"text":"Delaying the penalty","is_correct":false,"rationale":"That is a reprieve. Commutation actually lowers the penalty."},{"text":"Erasing the conviction entirely","is_correct":false,"rationale":"Commutation leaves the conviction in place and only lowers the penalty. Obliterating the offense is the effect of amnesty."},{"text":"Suspending the penalty on probation","is_correct":false,"rationale":"That is probation, granted by the court. Commutation is an executive act that reduces the penalty."}]$opt$::jsonb, $opt$[{"text":"Reducing the penalty imposed","isCorrect":true,"rationale":"Commutation reduces the penalty imposed without forgiving the offense.","is_correct":true},{"text":"Increasing penalty","isCorrect":false,"rationale":"'Increasing penalty' is incorrect. The correct answer is 'Reducing the penalty imposed'. Commutation reduces the penalty imposed without forgiving the offense. Review: Pardon and Amnesty.","is_correct":false},{"text":"Full pardon","isCorrect":false,"rationale":"'Full pardon' is incorrect. The correct answer is 'Reducing the penalty imposed'. Commutation reduces the penalty imposed without forgiving the offense. Review: Pardon and Amnesty.","is_correct":false},{"text":"No change","isCorrect":false,"rationale":"'No change' is incorrect. The correct answer is 'Reducing the penalty imposed'. Commutation reduces the penalty imposed without forgiving the offense. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb),
  ('ca_085', $opt$[{"text":"Presidential power to pardon","isCorrect":true,"rationale":"Executive clemency is the Presidents constitutional power to grant pardons.","is_correct":true},{"text":"Judicial power to suspend a sentence","is_correct":false,"rationale":"Courts may suspend a sentence through probation; clemency is the President's power under Art. VII, Sec. 19 of the Constitution."},{"text":"Legislative power to define penalties","is_correct":false,"rationale":"Congress defines crimes and penalties; clemency is an executive power."},{"text":"Police power to release","is_correct":false,"rationale":"The police cannot grant clemency; it belongs to the President."}]$opt$::jsonb, $opt$[{"text":"Presidential power to pardon","isCorrect":true,"rationale":"Executive clemency is the Presidents constitutional power to grant pardons.","is_correct":true},{"text":"Court decision","isCorrect":false,"rationale":"'Court decision' is incorrect. The correct answer is 'Presidential power to pardon'. Executive clemency is the Presidents constitutional power to grant pardons. Review: Pardon and Amnesty.","is_correct":false},{"text":"Police discretion","isCorrect":false,"rationale":"'Police discretion' is incorrect. The correct answer is 'Presidential power to pardon'. Executive clemency is the Presidents constitutional power to grant pardons. Review: Pardon and Amnesty.","is_correct":false},{"text":"Legislative act","isCorrect":false,"rationale":"'Legislative act' is incorrect. The correct answer is 'Presidential power to pardon'. Executive clemency is the Presidents constitutional power to grant pardons. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb),
  ('corr_131', $opt$[{"text":"Full forgiveness restoring all rights","isCorrect":true,"rationale":"Absolute pardon is complete forgiveness that restores all civil and political rights.","is_correct":true},{"text":"Forgiveness subject to conditions","is_correct":false,"rationale":"That is a conditional pardon. An absolute pardon carries no conditions."},{"text":"General pardon for a class of offenders","is_correct":false,"rationale":"That is amnesty, granted to a group, often political offenders. A pardon is given to an individual."},{"text":"Reduction of the penalty imposed","is_correct":false,"rationale":"That is commutation. An absolute pardon forgives the offender fully."}]$opt$::jsonb, $opt$[{"text":"Full forgiveness restoring all rights","isCorrect":true,"rationale":"Absolute pardon is complete forgiveness that restores all civil and political rights.","is_correct":true},{"text":"Conditional forgiveness","isCorrect":false,"rationale":"'Conditional forgiveness' is incorrect. The correct answer is 'Full forgiveness restoring all rights'. Absolute pardon is complete forgiveness that restores all civil and political rights. Review: Pardon and Amnesty.","is_correct":false},{"text":"Partial forgiveness","isCorrect":false,"rationale":"'Partial forgiveness' is incorrect. The correct answer is 'Full forgiveness restoring all rights'. Absolute pardon is complete forgiveness that restores all civil and political rights. Review: Pardon and Amnesty.","is_correct":false},{"text":"Temporary forgiveness","isCorrect":false,"rationale":"'Temporary forgiveness' is incorrect. The correct answer is 'Full forgiveness restoring all rights'. Absolute pardon is complete forgiveness that restores all civil and political rights. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb),
  ('corr_132', $opt$[{"text":"Pardon with conditions that must be followed","isCorrect":true,"rationale":"Conditional pardon releases the offender but requires compliance with certain conditions.","is_correct":true},{"text":"Pardon given to a group of offenders","is_correct":false,"rationale":"That is amnesty. A conditional pardon is given to one person and binds them to conditions."},{"text":"Release granted by the court before imprisonment","is_correct":false,"rationale":"That is probation. A conditional pardon is executive clemency, granted by the President after conviction."},{"text":"Release by the Board after serving the minimum","is_correct":false,"rationale":"That is parole. A conditional pardon comes from the President, and breaking its conditions is punished under Art. 159 RPC."}]$opt$::jsonb, $opt$[{"text":"Pardon with conditions that must be followed","isCorrect":true,"rationale":"Conditional pardon releases the offender but requires compliance with certain conditions.","is_correct":true},{"text":"Full pardon","isCorrect":false,"rationale":"'Full pardon' is incorrect. The correct answer is 'Pardon with conditions that must be followed'. Conditional pardon releases the offender but requires compliance with certain conditions. Review: Pardon and Amnesty.","is_correct":false},{"text":"Amnesty","isCorrect":false,"rationale":"'Amnesty' is incorrect. The correct answer is 'Pardon with conditions that must be followed'. Conditional pardon releases the offender but requires compliance with certain conditions. Review: Pardon and Amnesty.","is_correct":false},{"text":"Probation","isCorrect":false,"rationale":"'Probation' is incorrect. The correct answer is 'Pardon with conditions that must be followed'. Conditional pardon releases the offender but requires compliance with certain conditions. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb),
