  ('ca_094', $opt$[{"text":"Recovery program for addiction","isCorrect":true,"rationale":"The 12-step program is a structured recovery approach for addiction.","is_correct":true},{"text":"Step-by-step inmate classification system","is_correct":false,"rationale":"Classification is done by the reception and diagnostic center; the 12 steps are the Alcoholics Anonymous recovery model."},{"text":"Graduated system of disciplinary penalties","is_correct":false,"rationale":"Disciplinary penalties are not the 12 steps, which come from Alcoholics Anonymous."},{"text":"Reentry plan for parolees","is_correct":false,"rationale":"A reentry plan prepares an inmate for release. The 12 steps are a recovery model for addiction."}]$opt$::jsonb, $opt$[{"text":"Recovery program for addiction","isCorrect":true,"rationale":"The 12-step program is a structured recovery approach for addiction.","is_correct":true},{"text":"Security procedure","isCorrect":false,"rationale":"'Security procedure' is incorrect. The correct answer is 'Recovery program for addiction'. The 12-step program is a structured recovery approach for addiction. Review: Therapeutic Communities.","is_correct":false},{"text":"Classification system","isCorrect":false,"rationale":"'Classification system' is incorrect. The correct answer is 'Recovery program for addiction'. The 12-step program is a structured recovery approach for addiction. Review: Therapeutic Communities.","is_correct":false},{"text":"Disciplinary process","isCorrect":false,"rationale":"'Disciplinary process' is incorrect. The correct answer is 'Recovery program for addiction'. The 12-step program is a structured recovery approach for addiction. Review: Therapeutic Communities.","is_correct":false}]$opt$::jsonb),
  ('qb_ca_009', $opt$[{"text":"Discipline through strict isolation","is_correct":false,"rationale":"A therapeutic community works through a community of peers, not isolation."},{"text":"Drug rehabilitation through peer support","isCorrect":true,"rationale":"Therapeutic Communities use peer support and mutual self-help to treat substance abuse in correctional settings.","is_correct":true},{"text":"Job placement through outside employers","is_correct":false,"rationale":"That is work release or reentry. A TC focuses on recovery from drug dependence through peer support."},{"text":"Education through formal school classes","is_correct":false,"rationale":"That is the education program. A TC is a self-help community model for drug rehabilitation."}]$opt$::jsonb, $opt$[{"text":"Punishment","isCorrect":false,"rationale":"'Punishment' is incorrect. The correct answer is 'Drug rehabilitation through peer support'. Therapeutic Communities use peer support and mutual self-help to treat substance abuse in correctional settings. Review: Therapeutic Communities.","is_correct":false},{"text":"Drug rehabilitation through peer support","isCorrect":true,"rationale":"Therapeutic Communities use peer support and mutual self-help to treat substance abuse in correctional settings.","is_correct":true},{"text":"Isolation","isCorrect":false,"rationale":"'Isolation' is incorrect. The correct answer is 'Drug rehabilitation through peer support'. Therapeutic Communities use peer support and mutual self-help to treat substance abuse in correctional settings. Review: Therapeutic Communities.","is_correct":false},{"text":"Entertainment","isCorrect":false,"rationale":"'Entertainment' is incorrect. The correct answer is 'Drug rehabilitation through peer support'. Therapeutic Communities use peer support and mutual self-help to treat substance abuse in correctional settings. Review: Therapeutic Communities.","is_correct":false}]$opt$::jsonb),
  ('cd_040', $opt$[{"text":"Determine vehicle speed and direction","isCorrect":true,"rationale":"Skid marks help investigators determine vehicle speed and direction before impact.","is_correct":true},{"text":"Identify the make and model of the vehicle","is_correct":false,"rationale":"Skid marks show braking and motion. Make and model come from paint chips, parts or tire tread impressions."},{"text":"Estimate the time the collision occurred","is_correct":false,"rationale":"Skid marks do not show the time of the crash; witnesses, CCTV or records do."},{"text":"Find the driver's identity","is_correct":false,"rationale":"Skid marks show how the vehicle moved, not who was driving it."}]$opt$::jsonb, $opt$[{"text":"Determine vehicle speed and direction","isCorrect":true,"rationale":"Skid marks help investigators determine vehicle speed and direction before impact.","is_correct":true},{"text":"Identify vehicle","isCorrect":false,"rationale":"'Identify vehicle' is incorrect. The correct answer is 'Determine vehicle speed and direction'. Skid marks help investigators determine vehicle speed and direction before impact. Review: Accident Investigation.","is_correct":false},{"text":"Find witnesses","isCorrect":false,"rationale":"'Find witnesses' is incorrect. The correct answer is 'Determine vehicle speed and direction'. Skid marks help investigators determine vehicle speed and direction before impact. Review: Accident Investigation.","is_correct":false},{"text":"Determine fault","isCorrect":false,"rationale":"'Determine fault' is incorrect. The correct answer is 'Determine vehicle speed and direction'. Skid marks help investigators determine vehicle speed and direction before impact. Review: Accident Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_066', $opt$[{"text":"Examining tire marks to determine speed","isCorrect":true,"rationale":"Skid marks analysis helps determine vehicle speed before an accident.","is_correct":true},{"text":"Examining paint transfer to match vehicles","is_correct":false,"rationale":"Paint transfer links vehicles to a collision; it does not show how fast they were going."},{"text":"Examining tire tread to identify the brand","is_correct":false,"rationale":"Tread pattern analysis identifies the tire, not the vehicle's speed."},{"text":"Checking brake lights for damage","is_correct":false,"rationale":"Lamp examination shows whether lights were on at impact, not the speed."}]$opt$::jsonb, $opt$[{"text":"Examining tire marks to determine speed","isCorrect":true,"rationale":"Skid marks analysis helps determine vehicle speed before an accident.","is_correct":true},{"text":"Cleaning roads","isCorrect":false,"rationale":"'Cleaning roads' is incorrect. The correct answer is 'Examining tire marks to determine speed'. Skid marks analysis helps determine vehicle speed before an accident. Review: Accident Investigation.","is_correct":false},{"text":"Painting roads","isCorrect":false,"rationale":"'Painting roads' is incorrect. The correct answer is 'Examining tire marks to determine speed'. Skid marks analysis helps determine vehicle speed before an accident. Review: Accident Investigation.","is_correct":false},{"text":"Building roads","isCorrect":false,"rationale":"'Building roads' is incorrect. The correct answer is 'Examining tire marks to determine speed'. Skid marks analysis helps determine vehicle speed before an accident. Review: Accident Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_028', $opt$[{"text":"Willful burning and criminal intent","isCorrect":true,"rationale":"Arson requires willful or malicious burning with criminal intent.","is_correct":true},{"text":"Accidental burning and property damage","is_correct":false,"rationale":"Accidental fires are not arson; arson requires willful burning with criminal intent."},{"text":"Burning of property owned by another","is_correct":false,"rationale":"Ownership is not the key element; even burning one's own property can be arson under PD 1613. What matters is willful burning with intent."},{"text":"Burning caused by lightning","is_correct":false,"rationale":"Natural fires involve no human intent and are not arson."}]$opt$::jsonb, $opt$[{"text":"Willful burning and criminal intent","isCorrect":true,"rationale":"Arson requires willful or malicious burning with criminal intent.","is_correct":true},{"text":"Accidental fire","isCorrect":false,"rationale":"'Accidental fire' is incorrect. The correct answer is 'Willful burning and criminal intent'. Arson requires willful or malicious burning with criminal intent. Review: Arson Investigation.","is_correct":false},{"text":"Natural fire","isCorrect":false,"rationale":"'Natural fire' is incorrect. The correct answer is 'Willful burning and criminal intent'. Arson requires willful or malicious burning with criminal intent. Review: Arson Investigation.","is_correct":false},{"text":"Electrical fire","isCorrect":false,"rationale":"'Electrical fire' is incorrect. The correct answer is 'Willful burning and criminal intent'. Arson requires willful or malicious burning with criminal intent. Review: Arson Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_011', $opt$[{"text":"Documentation of evidence handling","isCorrect":true,"rationale":"Chain of custody is the chronological documentation showing the seizure, custody, control, and disposition of evidence.","is_correct":true},{"text":"Ranking of officers in the investigation","is_correct":false,"rationale":"That is the command structure. Chain of custody tracks who handled the evidence, when and why."},{"text":"Order in which witnesses testify in court","is_correct":false,"rationale":"The order of witnesses is a trial matter. Chain of custody documents how evidence was handled."},{"text":"List of suspects in the case","is_correct":false,"rationale":"A suspect list is not chain of custody, which records each transfer of the evidence."}]$opt$::jsonb, $opt$[{"text":"Documentation of evidence handling","isCorrect":true,"rationale":"Chain of custody is the chronological documentation showing the seizure, custody, control, and disposition of evidence.","is_correct":true},{"text":"Police hierarchy","isCorrect":false,"rationale":"'Police hierarchy' is incorrect. The correct answer is 'Documentation of evidence handling'. Chain of custody is the chronological documentation showing the seizure, custody, control, and disposition of evidence. Review: Crime Scene Investigation.","is_correct":false},{"text":"Court procedure","isCorrect":false,"rationale":"'Court procedure' is incorrect. The correct answer is 'Documentation of evidence handling'. Chain of custody is the chronological documentation showing the seizure, custody, control, and disposition of evidence. Review: Crime Scene Investigation.","is_correct":false},{"text":"Witness list","isCorrect":false,"rationale":"'Witness list' is incorrect. The correct answer is 'Documentation of evidence handling'. Chain of custody is the chronological documentation showing the seizure, custody, control, and disposition of evidence. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_064', $opt$[{"text":"Small materials transferred during crime","isCorrect":true,"rationale":"Trace evidence includes small materials like hair, fibers, and glass transferred during a crime.","is_correct":true},{"text":"Large objects that link a suspect to the scene","is_correct":false,"rationale":"Size matters here: trace evidence is small, like hair, fibers, glass or soil."},{"text":"Statements taken from eyewitnesses","is_correct":false,"rationale":"That is testimonial evidence, not trace evidence."},{"text":"Weapons recovered from the suspect","is_correct":false,"rationale":"Weapons are physical evidence, but not trace evidence, which is minute material transferred by contact."}]$opt$::jsonb, $opt$[{"text":"Small materials transferred during crime","isCorrect":true,"rationale":"Trace evidence includes small materials like hair, fibers, and glass transferred during a crime.","is_correct":true},{"text":"Large objects","isCorrect":false,"rationale":"'Large objects' is incorrect. The correct answer is 'Small materials transferred during crime'. Trace evidence includes small materials like hair, fibers, and glass transferred during a crime. Review: Crime Scene Investigation.","is_correct":false},{"text":"Weapons only","isCorrect":false,"rationale":"'Weapons only' is incorrect. The correct answer is 'Small materials transferred during crime'. Trace evidence includes small materials like hair, fibers, and glass transferred during a crime. Review: Crime Scene Investigation.","is_correct":false},{"text":"Documents only","isCorrect":false,"rationale":"'Documents only' is incorrect. The correct answer is 'Small materials transferred during crime'. Trace evidence includes small materials like hair, fibers, and glass transferred during a crime. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_085', $opt$[{"text":"Statements from witnesses","isCorrect":true,"rationale":"Testimonial evidence consists of verbal or written statements from witnesses.","is_correct":true},{"text":"Fingerprints lifted at the scene","is_correct":false,"rationale":"Fingerprints are physical evidence. Testimonial evidence comes from what witnesses say."},{"text":"Documents seized during a search","is_correct":false,"rationale":"Documents are documentary evidence, not testimonial evidence."},{"text":"DNA from blood stains","is_correct":false,"rationale":"DNA is physical (biological) evidence, not testimony."}]$opt$::jsonb, $opt$[{"text":"Statements from witnesses","isCorrect":true,"rationale":"Testimonial evidence consists of verbal or written statements from witnesses.","is_correct":true},{"text":"Fingerprints","isCorrect":false,"rationale":"'Fingerprints' is incorrect. The correct answer is 'Statements from witnesses'. Testimonial evidence consists of verbal or written statements from witnesses. Review: Crime Scene Investigation.","is_correct":false},{"text":"DNA","isCorrect":false,"rationale":"'DNA' is incorrect. The correct answer is 'Statements from witnesses'. Testimonial evidence consists of verbal or written statements from witnesses. Review: Crime Scene Investigation.","is_correct":false},{"text":"Weapons","isCorrect":false,"rationale":"'Weapons' is incorrect. The correct answer is 'Statements from witnesses'. Testimonial evidence consists of verbal or written statements from witnesses. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_094', $opt$[{"text":"Statement made believing death is imminent","isCorrect":true,"rationale":"A dying declaration is a statement made by someone who believes they are about to die.","is_correct":true},{"text":"Statement made against one's own interest","is_correct":false,"rationale":"That is a declaration against interest. A dying declaration is made under the belief that death is imminent."},{"text":"Written will made before the person dies","is_correct":false,"rationale":"A will disposes of property; it is not a statement about the cause of death."},{"text":"Statement made at the time of a startling event","is_correct":false,"rationale":"That is part of the res gestae. A dying declaration requires belief that death is imminent."}]$opt$::jsonb, $opt$[{"text":"Statement made believing death is imminent","isCorrect":true,"rationale":"A dying declaration is a statement made by someone who believes they are about to die.","is_correct":true},{"text":"Written will","isCorrect":false,"rationale":"'Written will' is incorrect. The correct answer is 'Statement made believing death is imminent'. A dying declaration is a statement made by someone who believes they are about to die. Review: Crime Scene Investigation.","is_correct":false},{"text":"Police report","isCorrect":false,"rationale":"'Police report' is incorrect. The correct answer is 'Statement made believing death is imminent'. A dying declaration is a statement made by someone who believes they are about to die. Review: Crime Scene Investigation.","is_correct":false},{"text":"Court testimony","isCorrect":false,"rationale":"'Court testimony' is incorrect. The correct answer is 'Statement made believing death is imminent'. A dying declaration is a statement made by someone who believes they are about to die. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_121', $opt$[{"text":"Covert observation of suspects","isCorrect":true,"rationale":"Surveillance involves secretly observing suspects to gather evidence.","is_correct":true},{"text":"Open questioning of possible witnesses","is_correct":false,"rationale":"That is interviewing. Surveillance watches suspects without their knowledge."},{"text":"Questioning a suspect in custody","is_correct":false,"rationale":"That is interrogation, not surveillance."},{"text":"Formal arrest of a suspect","is_correct":false,"rationale":"Arrest takes the suspect into custody; surveillance observes without them knowing."}]$opt$::jsonb, $opt$[{"text":"Covert observation of suspects","isCorrect":true,"rationale":"Surveillance involves secretly observing suspects to gather evidence.","is_correct":true},{"text":"Open questioning","isCorrect":false,"rationale":"'Open questioning' is incorrect. The correct answer is 'Covert observation of suspects'. Surveillance involves secretly observing suspects to gather evidence. Review: Criminal Investigation.","is_correct":false},{"text":"Arrest","isCorrect":false,"rationale":"'Arrest' is incorrect. The correct answer is 'Covert observation of suspects'. Surveillance involves secretly observing suspects to gather evidence. Review: Criminal Investigation.","is_correct":false},{"text":"Trial","isCorrect":false,"rationale":"'Trial' is incorrect. The correct answer is 'Covert observation of suspects'. Surveillance involves secretly observing suspects to gather evidence. Review: Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_122', $opt$[{"text":"Person providing information to police","isCorrect":true,"rationale":"An informant provides information to law enforcement about criminal activity.","is_correct":true},{"text":"Officer working under a false identity","is_correct":false,"rationale":"That is an undercover agent. An informant is a person, usually a civilian, who gives information to the police."},{"text":"Person who saw the crime and testifies","is_correct":false,"rationale":"That is an eyewitness. An informant gives information to the police and often never testifies."},{"text":"Officer who receives and records tips","is_correct":false,"rationale":"That is the handler, not the informant."}]$opt$::jsonb, $opt$[{"text":"Person providing information to police","isCorrect":true,"rationale":"An informant provides information to law enforcement about criminal activity.","is_correct":true},{"text":"Police officer","isCorrect":false,"rationale":"'Police officer' is incorrect. The correct answer is 'Person providing information to police'. An informant provides information to law enforcement about criminal activity. Review: Criminal Investigation.","is_correct":false},{"text":"Judge","isCorrect":false,"rationale":"'Judge' is incorrect. The correct answer is 'Person providing information to police'. An informant provides information to law enforcement about criminal activity. Review: Criminal Investigation.","is_correct":false},{"text":"Prosecutor","isCorrect":false,"rationale":"'Prosecutor' is incorrect. The correct answer is 'Person providing information to police'. An informant provides information to law enforcement about criminal activity. Review: Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_127', $opt$[{"text":"Searching area in two perpendicular directions","isCorrect":true,"rationale":"Grid search covers an area twice, walking perpendicular paths to ensure thorough coverage.","is_correct":true},{"text":"Searching in parallel lanes in one direction","is_correct":false,"rationale":"That is the strip or line search. The grid search runs the strip search twice, at right angles."},{"text":"Searching in circles from the center outward","is_correct":false,"rationale":"That is the spiral search."},{"text":"Dividing the area into pie-shaped sectors","is_correct":false,"rationale":"That is the wheel or ray search."}]$opt$::jsonb, $opt$[{"text":"Searching area in two perpendicular directions","isCorrect":true,"rationale":"Grid search covers an area twice, walking perpendicular paths to ensure thorough coverage.","is_correct":true},{"text":"Circle search","isCorrect":false,"rationale":"'Circle search' is incorrect. The correct answer is 'Searching area in two perpendicular directions'. Grid search covers an area twice, walking perpendicular paths to ensure thorough coverage. Review: Criminal Investigation.","is_correct":false},{"text":"Random search","isCorrect":false,"rationale":"'Random search' is incorrect. The correct answer is 'Searching area in two perpendicular directions'. Grid search covers an area twice, walking perpendicular paths to ensure thorough coverage. Review: Criminal Investigation.","is_correct":false},{"text":"Line search","isCorrect":false,"rationale":"'Line search' is incorrect. The correct answer is 'Searching area in two perpendicular directions'. Grid search covers an area twice, walking perpendicular paths to ensure thorough coverage. Review: Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_128', $opt$[{"text":"Starting from center moving outward in circles","isCorrect":true,"rationale":"Spiral search starts at the center (or perimeter) and moves in expanding (or contracting) circles.","is_correct":true},{"text":"Searching in parallel lanes across the area","is_correct":false,"rationale":"That is the strip or line search."},{"text":"Covering the area twice at right angles","is_correct":false,"rationale":"That is the grid, or double strip, search."},{"text":"Searching outward from the center along straight rays","is_correct":false,"rationale":"That is the wheel or ray search, which moves along straight lines from the center, not in circles."}]$opt$::jsonb, $opt$[{"text":"Starting from center moving outward in circles","isCorrect":true,"rationale":"Spiral search starts at the center (or perimeter) and moves in expanding (or contracting) circles.","is_correct":true},{"text":"Grid pattern","isCorrect":false,"rationale":"'Grid pattern' is incorrect. The correct answer is 'Starting from center moving outward in circles'. Spiral search starts at the center (or perimeter) and moves in expanding (or contracting) circles. Review: Criminal Investigation.","is_correct":false},{"text":"Random search","isCorrect":false,"rationale":"'Random search' is incorrect. The correct answer is 'Starting from center moving outward in circles'. Spiral search starts at the center (or perimeter) and moves in expanding (or contracting) circles. Review: Criminal Investigation.","is_correct":false},{"text":"Line search","isCorrect":false,"rationale":"'Line search' is incorrect. The correct answer is 'Starting from center moving outward in circles'. Spiral search starts at the center (or perimeter) and moves in expanding (or contracting) circles. Review: Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_021', $opt$[{"text":"Comprehensive Dangerous Drugs Act of 2002","isCorrect":true,"rationale":"RA 9165 is the Comprehensive Dangerous Drugs Act of 2002.","is_correct":true},{"text":"Dangerous Drugs Act of 1972","is_correct":false,"rationale":"That is RA 6425, which RA 9165 repealed and replaced."},{"text":"Comprehensive Firearms and Ammunition Regulation Act","is_correct":false,"rationale":"That is RA 10591 of 2013."},{"text":"Anti-Trafficking in Persons Act of 2003","is_correct":false,"rationale":"That is RA 9208."}]$opt$::jsonb, $opt$[{"text":"Comprehensive Dangerous Drugs Act of 2002","isCorrect":true,"rationale":"RA 9165 is the Comprehensive Dangerous Drugs Act of 2002.","is_correct":true},{"text":"Anti-Money Laundering Act","isCorrect":false,"rationale":"'Anti-Money Laundering Act' is incorrect. The correct answer is 'Comprehensive Dangerous Drugs Act of 2002'. RA 9165 is the Comprehensive Dangerous Drugs Act of 2002. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Firearms Act","isCorrect":false,"rationale":"'Firearms Act' is incorrect. The correct answer is 'Comprehensive Dangerous Drugs Act of 2002'. RA 9165 is the Comprehensive Dangerous Drugs Act of 2002. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Anti-Trafficking Act","isCorrect":false,"rationale":"'Anti-Trafficking Act' is incorrect. The correct answer is 'Comprehensive Dangerous Drugs Act of 2002'. RA 9165 is the Comprehensive Dangerous Drugs Act of 2002. Review: Drug Education and Vice Control.","is_correct":false}]$opt$::jsonb),
  ('cdi_067', $opt$[{"text":"Selling illegal drugs","isCorrect":true,"rationale":"Drug pushing is the illegal sale or distribution of dangerous drugs.","is_correct":true},{"text":"Using illegal drugs","is_correct":false,"rationale":"That is drug use. Pushing is selling, trading or giving away drugs."},{"text":"Manufacturing illegal drugs","is_correct":false,"rationale":"That is manufacture, a separate offense under RA 9165."},{"text":"Keeping drugs for one's own use","is_correct":false,"rationale":"That is possession, a separate offense under RA 9165."}]$opt$::jsonb, $opt$[{"text":"Selling illegal drugs","isCorrect":true,"rationale":"Drug pushing is the illegal sale or distribution of dangerous drugs.","is_correct":true},{"text":"Using drugs","isCorrect":false,"rationale":"'Using drugs' is incorrect. The correct answer is 'Selling illegal drugs'. Drug pushing is the illegal sale or distribution of dangerous drugs. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Manufacturing drugs","isCorrect":false,"rationale":"'Manufacturing drugs' is incorrect. The correct answer is 'Selling illegal drugs'. Drug pushing is the illegal sale or distribution of dangerous drugs. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Transporting only","isCorrect":false,"rationale":"'Transporting only' is incorrect. The correct answer is 'Selling illegal drugs'. Drug pushing is the illegal sale or distribution of dangerous drugs. Review: Drug Education and Vice Control.","is_correct":false}]$opt$::jsonb),
  ('cdi_068', $opt$[{"text":"Physical or psychological need for drugs","isCorrect":true,"rationale":"Drug dependency is the compulsive physical or psychological need for drugs.","is_correct":true},{"text":"Occasional use of drugs at social events","is_correct":false,"rationale":"That is recreational or occasional use; dependency is a compelling physical or psychological need for the drug."},{"text":"Use of drugs under a doctor's prescription","is_correct":false,"rationale":"Medical use under prescription is not dependency by itself."},{"text":"First-time experimentation with drugs","is_correct":false,"rationale":"Experimentation is trying a drug, not being dependent on it."}]$opt$::jsonb, $opt$[{"text":"Physical or psychological need for drugs","isCorrect":true,"rationale":"Drug dependency is the compulsive physical or psychological need for drugs.","is_correct":true},{"text":"Occasional use","isCorrect":false,"rationale":"'Occasional use' is incorrect. The correct answer is 'Physical or psychological need for drugs'. Drug dependency is the compulsive physical or psychological need for drugs. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Medical use","isCorrect":false,"rationale":"'Medical use' is incorrect. The correct answer is 'Physical or psychological need for drugs'. Drug dependency is the compulsive physical or psychological need for drugs. Review: Drug Education and Vice Control.","is_correct":false},{"text":"No use","isCorrect":false,"rationale":"'No use' is incorrect. The correct answer is 'Physical or psychological need for drugs'. Drug dependency is the compulsive physical or psychological need for drugs. Review: Drug Education and Vice Control.","is_correct":false}]$opt$::jsonb),
  ('cd_025', $opt$[{"text":"Heat, Fuel, Oxygen, Chemical chain reaction","isCorrect":true,"rationale":"The fire tetrahedron adds chemical chain reaction to the fire triangle elements.","is_correct":true},{"text":"Heat, Fuel, and Oxygen only","is_correct":false,"rationale":"That is the fire triangle. The tetrahedron adds the chemical chain reaction."},{"text":"Heat, Fuel, Oxygen, and Water vapor","is_correct":false,"rationale":"Water vapor is not an element of fire; the fourth side is the chemical chain reaction."},{"text":"Heat, Smoke, Flame, and Chemical chain reaction","is_correct":false,"rationale":"Smoke and flame are products of fire, not its elements."}]$opt$::jsonb, $opt$[{"text":"Heat, Fuel, Oxygen, Chemical chain reaction","isCorrect":true,"rationale":"The fire tetrahedron adds chemical chain reaction to the fire triangle elements.","is_correct":true},{"text":"Only heat and fuel","isCorrect":false,"rationale":"'Only heat and fuel' is incorrect. The correct answer is 'Heat, Fuel, Oxygen, Chemical chain reaction'. The fire tetrahedron adds chemical chain reaction to the fire triangle elements. Review: Fire Technology.","is_correct":false},{"text":"Only oxygen","isCorrect":false,"rationale":"'Only oxygen' is incorrect. The correct answer is 'Heat, Fuel, Oxygen, Chemical chain reaction'. The fire tetrahedron adds chemical chain reaction to the fire triangle elements. Review: Fire Technology.","is_correct":false},{"text":"Fire triangle","isCorrect":false,"rationale":"'Fire triangle' is incorrect. The correct answer is 'Heat, Fuel, Oxygen, Chemical chain reaction'. The fire tetrahedron adds chemical chain reaction to the fire triangle elements. Review: Fire Technology.","is_correct":false}]$opt$::jsonb),
  ('cd_027', $opt$[{"text":"Substance used to start or spread fire","isCorrect":true,"rationale":"An accelerant is a substance like gasoline used to start or accelerate the spread of fire.","is_correct":true},{"text":"Substance used to slow the spread of fire","is_correct":false,"rationale":"That is a fire retardant, the opposite of an accelerant."},{"text":"Substance used to put out a fire","is_correct":false,"rationale":"That is an extinguishing agent."},{"text":"Device used to detect smoke early","is_correct":false,"rationale":"That is a smoke detector."}]$opt$::jsonb, $opt$[{"text":"Substance used to start or spread fire","isCorrect":true,"rationale":"An accelerant is a substance like gasoline used to start or accelerate the spread of fire.","is_correct":true},{"text":"Fire extinguisher","isCorrect":false,"rationale":"'Fire extinguisher' is incorrect. The correct answer is 'Substance used to start or spread fire'. An accelerant is a substance like gasoline used to start or accelerate the spread of fire. Review: Fire Technology.","is_correct":false},{"text":"Fire retardant","isCorrect":false,"rationale":"'Fire retardant' is incorrect. The correct answer is 'Substance used to start or spread fire'. An accelerant is a substance like gasoline used to start or accelerate the spread of fire. Review: Fire Technology.","is_correct":false},{"text":"Water","isCorrect":false,"rationale":"'Water' is incorrect. The correct answer is 'Substance used to start or spread fire'. An accelerant is a substance like gasoline used to start or accelerate the spread of fire. Review: Fire Technology.","is_correct":false}]$opt$::jsonb),
  ('cdi_070', $opt$[{"text":"Substances used to spread fire faster","isCorrect":true,"rationale":"Accelerants are flammable substances used to start or spread fire in arson.","is_correct":true},{"text":"Materials treated to resist burning","is_correct":false,"rationale":"That is fire-resistant material, the opposite of an accelerant."},{"text":"Chemicals used to put out burning fuels","is_correct":false,"rationale":"Those are extinguishing agents."},{"text":"Residue left after a fire burns out","is_correct":false,"rationale":"That is fire debris; it may contain traces of an accelerant, but it is not the accelerant."}]$opt$::jsonb, $opt$[{"text":"Substances used to spread fire faster","isCorrect":true,"rationale":"Accelerants are flammable substances used to start or spread fire in arson.","is_correct":true},{"text":"Fire extinguishers","isCorrect":false,"rationale":"'Fire extinguishers' is incorrect. The correct answer is 'Substances used to spread fire faster'. Accelerants are flammable substances used to start or spread fire in arson. Review: Fire Technology.","is_correct":false},{"text":"Fireproof materials","isCorrect":false,"rationale":"'Fireproof materials' is incorrect. The correct answer is 'Substances used to spread fire faster'. Accelerants are flammable substances used to start or spread fire in arson. Review: Fire Technology.","is_correct":false},{"text":"Safety equipment","isCorrect":false,"rationale":"'Safety equipment' is incorrect. The correct answer is 'Substances used to spread fire faster'. Accelerants are flammable substances used to start or spread fire in arson. Review: Fire Technology.","is_correct":false}]$opt$::jsonb),
  ('cd_001', $opt$[{"text":"Information, Interrogation, Instrumentation","isCorrect":true,"rationale":"The 3 I's are Information (gathering data), Interrogation (questioning), and Instrumentation (forensic tools).","is_correct":true},{"text":"Information, Interview, Investigation","is_correct":false,"rationale":"Interviewing is part of interrogation, and investigation is the whole process; the third I is instrumentation."},{"text":"Intelligence, Interview, Instrumentation","is_correct":false,"rationale":"Intelligence and interview are not the first two I's; they are information and interrogation."},{"text":"Information, Identification, Instrumentation","is_correct":false,"rationale":"Identification is an aim of investigation, not one of its tools; the second I is interrogation."}]$opt$::jsonb, $opt$[{"text":"Information, Interrogation, Instrumentation","isCorrect":true,"rationale":"The 3 I's are Information (gathering data), Interrogation (questioning), and Instrumentation (forensic tools).","is_correct":true},{"text":"Interview, Inspect, Investigate","isCorrect":false,"rationale":"'Interview, Inspect, Investigate' is incorrect. The correct answer is 'Information, Interrogation, Instrumentation'. The 3 I's are Information (gathering data), Interrogation (questioning), and Instrumentation (forensic tools). Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Identify, Isolate, Interrogate","isCorrect":false,"rationale":"'Identify, Isolate, Interrogate' is incorrect. The correct answer is 'Information, Interrogation, Instrumentation'. The 3 I's are Information (gathering data), Interrogation (questioning), and Instrumentation (forensic tools). Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Input, Investigate, Interpret","isCorrect":false,"rationale":"'Input, Investigate, Interpret' is incorrect. The correct answer is 'Information, Interrogation, Instrumentation'. The 3 I's are Information (gathering data), Interrogation (questioning), and Instrumentation (forensic tools). Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_010', $opt$[{"text":"Do not touch anything","isCorrect":true,"rationale":"The cardinal rule is to not touch, move, or alter anything at the crime scene until properly documented.","is_correct":true},{"text":"Photograph the scene first","is_correct":false,"rationale":"Photography comes early, but the cardinal rule is not to touch, alter or move anything until it is documented."},{"text":"Interview witnesses at once","is_correct":false,"rationale":"Witnesses are interviewed, but the cardinal rule protects the scene from being disturbed."},{"text":"Call for backup","is_correct":false,"rationale":"Backup may be needed, but the rule of the scene is not to touch anything."}]$opt$::jsonb, $opt$[{"text":"Do not touch anything","isCorrect":true,"rationale":"The cardinal rule is to not touch, move, or alter anything at the crime scene until properly documented.","is_correct":true},{"text":"Take photos first","isCorrect":false,"rationale":"'Take photos first' is incorrect. The correct answer is 'Do not touch anything'. The cardinal rule is to not touch, move, or alter anything at the crime scene until properly documented. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Interview witnesses","isCorrect":false,"rationale":"'Interview witnesses' is incorrect. The correct answer is 'Do not touch anything'. The cardinal rule is to not touch, move, or alter anything at the crime scene until properly documented. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Call for backup","isCorrect":false,"rationale":"'Call for backup' is incorrect. The correct answer is 'Do not touch anything'. The cardinal rule is to not touch, move, or alter anything at the crime scene until properly documented. Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_018', $opt$[{"text":"Method of operation used by criminal","isCorrect":true,"rationale":"Modus operandi (MO) is the particular method or pattern used by a criminal in committing crimes.","is_correct":true},{"text":"Reason the criminal committed the crime","is_correct":false,"rationale":"That is the motive, not the method."},{"text":"Place where the crime was committed","is_correct":false,"rationale":"That is the place of the crime, not the offender's method."},{"text":"Time when the crime was committed","is_correct":false,"rationale":"The time is a detail of the crime; modus operandi is the offender's method."}]$opt$::jsonb, $opt$[{"text":"Method of operation used by criminal","isCorrect":true,"rationale":"Modus operandi (MO) is the particular method or pattern used by a criminal in committing crimes.","is_correct":true},{"text":"Motive for crime","isCorrect":false,"rationale":"'Motive for crime' is incorrect. The correct answer is 'Method of operation used by criminal'. Modus operandi (MO) is the particular method or pattern used by a criminal in committing crimes. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Type of weapon","isCorrect":false,"rationale":"'Type of weapon' is incorrect. The correct answer is 'Method of operation used by criminal'. Modus operandi (MO) is the particular method or pattern used by a criminal in committing crimes. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Time of crime","isCorrect":false,"rationale":"'Time of crime' is incorrect. The correct answer is 'Method of operation used by criminal'. Modus operandi (MO) is the particular method or pattern used by a criminal in committing crimes. Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_020', $opt$[{"text":"Statement of fact tending to prove guilt","isCorrect":true,"rationale":"An admission is a statement of fact that tends to prove guilt but is not a full confession.","is_correct":true},{"text":"Full acknowledgment of guilt for the crime","is_correct":false,"rationale":"That is a confession. An admission acknowledges facts that tend to prove guilt without admitting the crime itself."},{"text":"Statement that the accused was elsewhere","is_correct":false,"rationale":"That is an alibi."},{"text":"Statement denying any part in the crime","is_correct":false,"rationale":"That is a denial."}]$opt$::jsonb, $opt$[{"text":"Statement of fact tending to prove guilt","isCorrect":true,"rationale":"An admission is a statement of fact that tends to prove guilt but is not a full confession.","is_correct":true},{"text":"Full confession","isCorrect":false,"rationale":"'Full confession' is incorrect. The correct answer is 'Statement of fact tending to prove guilt'. An admission is a statement of fact that tends to prove guilt but is not a full confession. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Denial","isCorrect":false,"rationale":"'Denial' is incorrect. The correct answer is 'Statement of fact tending to prove guilt'. An admission is a statement of fact that tends to prove guilt but is not a full confession. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Alibi","isCorrect":false,"rationale":"'Alibi' is incorrect. The correct answer is 'Statement of fact tending to prove guilt'. An admission is a statement of fact that tends to prove guilt but is not a full confession. Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_062', $opt$[{"text":"Body of the crime - proof crime occurred","isCorrect":true,"rationale":"Corpus delicti means the body of the crime - evidence that a crime actually occurred.","is_correct":true},{"text":"The body of the victim found at the scene","is_correct":false,"rationale":"Corpus delicti means the body of the crime, the fact that a crime was committed, not literally the corpse."},{"text":"Proof of who committed the crime","is_correct":false,"rationale":"The identity of the offender is separate from corpus delicti."},{"text":"The weapon used to commit the crime","is_correct":false,"rationale":"A weapon may help prove it, but corpus delicti is the fact that the crime happened."}]$opt$::jsonb, $opt$[{"text":"Body of the crime - proof crime occurred","isCorrect":true,"rationale":"Corpus delicti means the body of the crime - evidence that a crime actually occurred.","is_correct":true},{"text":"Dead body only","isCorrect":false,"rationale":"'Dead body only' is incorrect. The correct answer is 'Body of the crime - proof crime occurred'. Corpus delicti means the body of the crime - evidence that a crime actually occurred. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Criminal identity","isCorrect":false,"rationale":"'Criminal identity' is incorrect. The correct answer is 'Body of the crime - proof crime occurred'. Corpus delicti means the body of the crime - evidence that a crime actually occurred. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Weapon used","isCorrect":false,"rationale":"'Weapon used' is incorrect. The correct answer is 'Body of the crime - proof crime occurred'. Corpus delicti means the body of the crime - evidence that a crime actually occurred. Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_082', $opt$[{"text":"Body of the crime or proof crime occurred","isCorrect":true,"rationale":"Corpus delicti means body of the crime - evidence that a crime was committed.","is_correct":true},{"text":"The corpse of the victim","is_correct":false,"rationale":"Corpus delicti means the body of the crime, the fact that a crime was committed, not literally the corpse."},{"text":"Testimony of the main eyewitness","is_correct":false,"rationale":"Testimony may help prove it; corpus delicti is the fact that a crime was committed."},{"text":"Identity of the person who did the crime","is_correct":false,"rationale":"Who committed the crime is the identity of the offender, a separate matter from corpus delicti."}]$opt$::jsonb, $opt$[{"text":"Body of the crime or proof crime occurred","isCorrect":true,"rationale":"Corpus delicti means body of the crime - evidence that a crime was committed.","is_correct":true},{"text":"Dead body","isCorrect":false,"rationale":"'Dead body' is incorrect. The correct answer is 'Body of the crime or proof crime occurred'. Corpus delicti means body of the crime - evidence that a crime was committed. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Crime weapon","isCorrect":false,"rationale":"'Crime weapon' is incorrect. The correct answer is 'Body of the crime or proof crime occurred'. Corpus delicti means body of the crime - evidence that a crime was committed. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Witness testimony","isCorrect":false,"rationale":"'Witness testimony' is incorrect. The correct answer is 'Body of the crime or proof crime occurred'. Corpus delicti means body of the crime - evidence that a crime was committed. Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_087', $opt$[{"text":"Systematic approach to solve crimes","isCorrect":true,"rationale":"The investigative process is a structured approach to gather evidence and solve crimes.","is_correct":true},{"text":"Random checking of possible suspects","is_correct":false,"rationale":"Investigation is systematic, not random."},{"text":"Trial of the accused before a judge","is_correct":false,"rationale":"Trial is a court process that follows investigation."},{"text":"Filing of charges by the prosecutor","is_correct":false,"rationale":"Filing charges comes after the investigation."}]$opt$::jsonb, $opt$[{"text":"Systematic approach to solve crimes","isCorrect":true,"rationale":"The investigative process is a structured approach to gather evidence and solve crimes.","is_correct":true},{"text":"Random search","isCorrect":false,"rationale":"'Random search' is incorrect. The correct answer is 'Systematic approach to solve crimes'. The investigative process is a structured approach to gather evidence and solve crimes. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Media involvement","isCorrect":false,"rationale":"'Media involvement' is incorrect. The correct answer is 'Systematic approach to solve crimes'. The investigative process is a structured approach to gather evidence and solve crimes. Review: Fundamentals of Criminal Investigation.","is_correct":false},{"text":"Public trial","isCorrect":false,"rationale":"'Public trial' is incorrect. The correct answer is 'Systematic approach to solve crimes'. The investigative process is a structured approach to gather evidence and solve crimes. Review: Fundamentals of Criminal Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_136', $opt$[{"text":"Hierarchical structure with ongoing criminal enterprise","isCorrect":true,"rationale":"Organized crime involves structured groups engaged in ongoing criminal enterprises.","is_correct":true},{"text":"Single criminal act by a group of friends","is_correct":false,"rationale":"Organized crime is a continuing enterprise, not a single act."},{"text":"Spontaneous violence committed by a crowd during civil unrest","is_correct":false,"rationale":"That is mob or riot behavior, which has no lasting structure."},{"text":"Loose group of youths committing petty crimes together","is_correct":false,"rationale":"That describes a delinquent group without the hierarchy and continuity of organized crime."}]$opt$::jsonb, $opt$[{"text":"Hierarchical structure with ongoing criminal enterprise","isCorrect":true,"rationale":"Organized crime involves structured groups engaged in ongoing criminal enterprises.","is_correct":true},{"text":"Single criminal act","isCorrect":false,"rationale":"'Single criminal act' is incorrect. The correct answer is 'Hierarchical structure with ongoing criminal enterprise'. Organized crime involves structured groups engaged in ongoing criminal enterprises. Review: Organized Crime.","is_correct":false},{"text":"Random crimes","isCorrect":false,"rationale":"'Random crimes' is incorrect. The correct answer is 'Hierarchical structure with ongoing criminal enterprise'. Organized crime involves structured groups engaged in ongoing criminal enterprises. Review: Organized Crime.","is_correct":false},{"text":"Individual theft","isCorrect":false,"rationale":"'Individual theft' is incorrect. The correct answer is 'Hierarchical structure with ongoing criminal enterprise'. Organized crime involves structured groups engaged in ongoing criminal enterprises. Review: Organized Crime.","is_correct":false}]$opt$::jsonb),
  ('cdi_086', $opt$[{"text":"Inducing someone to commit crime they would not otherwise commit","isCorrect":true,"rationale":"Entrapment is when law enforcement induces someone to commit a crime they were not predisposed to commit.","is_correct":true},{"text":"Arresting a suspect caught in the act without a warrant","is_correct":false,"rationale":"That is a warrantless arrest in flagrante delicto under Rule 113, Sec. 5. It does not involve inducing anyone."},{"text":"Secretly recording a suspect's private phone conversations","is_correct":false,"rationale":"That is wiretapping, which RA 4200 prohibits except under court authority."},{"text":"Following a suspect secretly to learn their daily routine","is_correct":false,"rationale":"That is surveillance, also called tailing or shadowing."}]$opt$::jsonb, $opt$[{"text":"Inducing someone to commit crime they would not otherwise commit","isCorrect":true,"rationale":"Entrapment is when law enforcement induces someone to commit a crime they were not predisposed to commit.","is_correct":true},{"text":"Legal undercover operation","isCorrect":false,"rationale":"'Legal undercover operation' is incorrect. The correct answer is 'Inducing someone to commit crime they would not otherwise commit'. Entrapment is when law enforcement induces someone to commit a crime they were not predisposed to commit. Review: Special Crime Investigation.","is_correct":false},{"text":"Arrest procedure","isCorrect":false,"rationale":"'Arrest procedure' is incorrect. The correct answer is 'Inducing someone to commit crime they would not otherwise commit'. Entrapment is when law enforcement induces someone to commit a crime they were not predisposed to commit. Review: Special Crime Investigation.","is_correct":false},{"text":"Evidence collection","isCorrect":false,"rationale":"'Evidence collection' is incorrect. The correct answer is 'Inducing someone to commit crime they would not otherwise commit'. Entrapment is when law enforcement induces someone to commit a crime they were not predisposed to commit. Review: Special Crime Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_091', $opt$[{"text":"Covert observation of persons or places","isCorrect":true,"rationale":"Surveillance is secret observation to gather intelligence.","is_correct":true},{"text":"Open patrol of an assigned beat","is_correct":false,"rationale":"Patrol is visible police presence; surveillance is covert."},{"text":"Questioning residents door to door","is_correct":false,"rationale":"That is canvassing, not surveillance."},{"text":"Searching persons at a checkpoint","is_correct":false,"rationale":"A checkpoint search is open and visible; surveillance is covert."}]$opt$::jsonb, $opt$[{"text":"Covert observation of persons or places","isCorrect":true,"rationale":"Surveillance is secret observation to gather intelligence.","is_correct":true},{"text":"Open patrol","isCorrect":false,"rationale":"'Open patrol' is incorrect. The correct answer is 'Covert observation of persons or places'. Surveillance is secret observation to gather intelligence. Review: Special Crime Investigation.","is_correct":false},{"text":"Traffic direction","isCorrect":false,"rationale":"'Traffic direction' is incorrect. The correct answer is 'Covert observation of persons or places'. Surveillance is secret observation to gather intelligence. Review: Special Crime Investigation.","is_correct":false},{"text":"Public speaking","isCorrect":false,"rationale":"'Public speaking' is incorrect. The correct answer is 'Covert observation of persons or places'. Surveillance is secret observation to gather intelligence. Review: Special Crime Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_092', $opt$[{"text":"Observing target before operation","isCorrect":true,"rationale":"Casing involves preliminary observation of a target location.","is_correct":true},{"text":"Following a suspect on foot","is_correct":false,"rationale":"That is tailing or shadowing; casing studies a place before an operation."},{"text":"Building a case file for prosecution","is_correct":false,"rationale":"That is case preparation, not casing."},{"text":"Interviewing neighbors after the crime","is_correct":false,"rationale":"That is a neighborhood canvass."}]$opt$::jsonb, $opt$[{"text":"Observing target before operation","isCorrect":true,"rationale":"Casing involves preliminary observation of a target location.","is_correct":true},{"text":"Opening cases","isCorrect":false,"rationale":"'Opening cases' is incorrect. The correct answer is 'Observing target before operation'. Casing involves preliminary observation of a target location. Review: Special Crime Investigation.","is_correct":false},{"text":"Court filing","isCorrect":false,"rationale":"'Court filing' is incorrect. The correct answer is 'Observing target before operation'. Casing involves preliminary observation of a target location. Review: Special Crime Investigation.","is_correct":false},{"text":"Evidence storage","isCorrect":false,"rationale":"'Evidence storage' is incorrect. The correct answer is 'Observing target before operation'. Casing involves preliminary observation of a target location. Review: Special Crime Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_095', $opt$[{"text":"Investigation using concealed identity","isCorrect":true,"rationale":"Undercover operations involve officers using concealed identities.","is_correct":true},{"text":"Investigation using hidden cameras only","is_correct":false,"rationale":"Hidden cameras are technical surveillance; undercover work means an officer takes on a false identity."},{"text":"Patrol in uniform to deter crime","is_correct":false,"rationale":"That is visible patrol, the opposite of undercover work."},{"text":"Questioning of a suspect under custody","is_correct":false,"rationale":"That is custodial interrogation."}]$opt$::jsonb, $opt$[{"text":"Investigation using concealed identity","isCorrect":true,"rationale":"Undercover operations involve officers using concealed identities.","is_correct":true},{"text":"Uniformed patrol","isCorrect":false,"rationale":"'Uniformed patrol' is incorrect. The correct answer is 'Investigation using concealed identity'. Undercover operations involve officers using concealed identities. Review: Special Crime Investigation.","is_correct":false},{"text":"Traffic duty","isCorrect":false,"rationale":"'Traffic duty' is incorrect. The correct answer is 'Investigation using concealed identity'. Undercover operations involve officers using concealed identities. Review: Special Crime Investigation.","is_correct":false},{"text":"Administrative work","isCorrect":false,"rationale":"'Administrative work' is incorrect. The correct answer is 'Investigation using concealed identity'. Undercover operations involve officers using concealed identities. Review: Special Crime Investigation.","is_correct":false}]$opt$::jsonb),
  ('cdi_135', $opt$[{"text":"Illegal inducement to commit crime","isCorrect":true,"rationale":"Instigation is illegal, where police induce someone to commit a crime they wouldn't otherwise commit.","is_correct":true},{"text":"Lawful trap for a willing offender","is_correct":false,"rationale":"That is entrapment, which is allowed. In instigation the officer creates the criminal intent, so it is a defense."},{"text":"Buy-bust operation against drug sellers","is_correct":false,"rationale":"A buy-bust is a form of entrapment, which is lawful."},{"text":"Tailing a suspect","is_correct":false,"rationale":"That is surveillance, not inducement."}]$opt$::jsonb, $opt$[{"text":"Illegal inducement to commit crime","isCorrect":true,"rationale":"Instigation is illegal, where police induce someone to commit a crime they wouldn't otherwise commit.","is_correct":true},{"text":"Legal entrapment","isCorrect":false,"rationale":"'Legal entrapment' is incorrect. The correct answer is 'Illegal inducement to commit crime'. Instigation is illegal, where police induce someone to commit a crime they wouldn't otherwise commit. Review: Special Crime Investigation.","is_correct":false},{"text":"Surveillance","isCorrect":false,"rationale":"'Surveillance' is incorrect. The correct answer is 'Illegal inducement to commit crime'. Instigation is illegal, where police induce someone to commit a crime they wouldn't otherwise commit. Review: Special Crime Investigation.","is_correct":false},{"text":"Investigation","isCorrect":false,"rationale":"'Investigation' is incorrect. The correct answer is 'Illegal inducement to commit crime'. Instigation is illegal, where police induce someone to commit a crime they wouldn't otherwise commit. Review: Special Crime Investigation.","is_correct":false}]$opt$::jsonb),
  ('cd_029', $opt$[{"text":"Engineering, Education, Enforcement","isCorrect":true,"rationale":"The 3 Es are Engineering (road design), Education (driver training), and Enforcement (traffic laws).","is_correct":true},{"text":"Engineering, Education, Emergency","is_correct":false,"rationale":"Emergency response is not one of the 3 Es; the third is enforcement."},{"text":"Enforcement, Evaluation, Economy","is_correct":false,"rationale":"Evaluation and economy are not among the 3 Es."},{"text":"Education, Enforcement, Environment","is_correct":false,"rationale":"Environment is sometimes added as a later E, but the original three are engineering, education and enforcement."}]$opt$::jsonb, $opt$[{"text":"Engineering, Education, Enforcement","isCorrect":true,"rationale":"The 3 Es are Engineering (road design), Education (driver training), and Enforcement (traffic laws).","is_correct":true},{"text":"Entry, Exit, Emergency","isCorrect":false,"rationale":"'Entry, Exit, Emergency' is incorrect. The correct answer is 'Engineering, Education, Enforcement'. The 3 Es are Engineering (road design), Education (driver training), and Enforcement (traffic laws). Review: Traffic Management.","is_correct":false},{"text":"Evaluate, Execute, Enforce","isCorrect":false,"rationale":"'Evaluate, Execute, Enforce' is incorrect. The correct answer is 'Engineering, Education, Enforcement'. The 3 Es are Engineering (road design), Education (driver training), and Enforcement (traffic laws). Review: Traffic Management.","is_correct":false},{"text":"Examine, Explain, Execute","isCorrect":false,"rationale":"'Examine, Explain, Execute' is incorrect. The correct answer is 'Engineering, Education, Enforcement'. The 3 Es are Engineering (road design), Education (driver training), and Enforcement (traffic laws). Review: Traffic Management.","is_correct":false}]$opt$::jsonb),
  ('cdi_090', $opt$[{"text":"Targeting specific violations in problem areas","isCorrect":true,"rationale":"Selective enforcement focuses resources on specific violations and locations.","is_correct":true},{"text":"Checking every vehicle at fixed checkpoints","is_correct":false,"rationale":"That is blanket enforcement. Selective enforcement targets the violations and places that cause crashes."},{"text":"Issuing warnings instead of tickets","is_correct":false,"rationale":"That is a leniency policy, not selective enforcement."},{"text":"Enforcing only on holidays and weekends","is_correct":false,"rationale":"Selective enforcement is based on which violations and places cause accidents, not on the calendar."}]$opt$::jsonb, $opt$[{"text":"Targeting specific violations in problem areas","isCorrect":true,"rationale":"Selective enforcement focuses resources on specific violations and locations.","is_correct":true},{"text":"Random enforcement","isCorrect":false,"rationale":"'Random enforcement' is incorrect. The correct answer is 'Targeting specific violations in problem areas'. Selective enforcement focuses resources on specific violations and locations. Review: Traffic Management.","is_correct":false},{"text":"No enforcement","isCorrect":false,"rationale":"'No enforcement' is incorrect. The correct answer is 'Targeting specific violations in problem areas'. Selective enforcement focuses resources on specific violations and locations. Review: Traffic Management.","is_correct":false},{"text":"Universal checkpoints","isCorrect":false,"rationale":"'Universal checkpoints' is incorrect. The correct answer is 'Targeting specific violations in problem areas'. Selective enforcement focuses resources on specific violations and locations. Review: Traffic Management.","is_correct":false}]$opt$::jsonb),
  ('cdi_129', $opt$[{"text":"Designing roads and traffic systems","isCorrect":true,"rationale":"Traffic engineering involves planning and designing roads, signals, and traffic flow systems.","is_correct":true},{"text":"Enforcing traffic laws on the road","is_correct":false,"rationale":"That is traffic enforcement."},{"text":"Teaching drivers and pedestrians road safety","is_correct":false,"rationale":"That is traffic education."},{"text":"Investigating the causes of road crashes","is_correct":false,"rationale":"That is accident investigation."}]$opt$::jsonb, $opt$[{"text":"Designing roads and traffic systems","isCorrect":true,"rationale":"Traffic engineering involves planning and designing roads, signals, and traffic flow systems.","is_correct":true},{"text":"Enforcing traffic laws","isCorrect":false,"rationale":"'Enforcing traffic laws' is incorrect. The correct answer is 'Designing roads and traffic systems'. Traffic engineering involves planning and designing roads, signals, and traffic flow systems. Review: Traffic Management.","is_correct":false},{"text":"Accident investigation","isCorrect":false,"rationale":"'Accident investigation' is incorrect. The correct answer is 'Designing roads and traffic systems'. Traffic engineering involves planning and designing roads, signals, and traffic flow systems. Review: Traffic Management.","is_correct":false},{"text":"Driver education","isCorrect":false,"rationale":"'Driver education' is incorrect. The correct answer is 'Designing roads and traffic systems'. Traffic engineering involves planning and designing roads, signals, and traffic flow systems. Review: Traffic Management.","is_correct":false}]$opt$::jsonb),
  ('cj_025', $opt$[{"text":"Attack ensuring no risk to offender from victim defense","isCorrect":true,"rationale":"Treachery means employing means that ensure the commission of the crime without risk from the victim's defense.","is_correct":true},{"text":"Taking advantage of superior strength to overpower the victim","is_correct":false,"rationale":"That is abuse of superior strength, a separate qualifying circumstance. Treachery is about means that remove any risk from the victim's defense."},{"text":"Deliberately choosing nighttime to commit the crime","is_correct":false,"rationale":"That is nocturnity, a separate aggravating circumstance."},{"text":"Planning the crime long before carrying it out","is_correct":false,"rationale":"That is evident premeditation, not treachery."}]$opt$::jsonb, $opt$[{"text":"Attack ensuring no risk to offender from victim defense","isCorrect":true,"rationale":"Treachery means employing means that ensure the commission of the crime without risk from the victim's defense.","is_correct":true},{"text":"Use of superior strength","isCorrect":false,"rationale":"'Use of superior strength' is incorrect. The correct answer is 'Attack ensuring no risk to offender from victim defense'. Treachery means employing means that ensure the commission of the crime without risk from the victim's defense. Review: Aggravating Circumstances.","is_correct":false},{"text":"Nighttime attack","isCorrect":false,"rationale":"'Nighttime attack' is incorrect. The correct answer is 'Attack ensuring no risk to offender from victim defense'. Treachery means employing means that ensure the commission of the crime without risk from the victim's defense. Review: Aggravating Circumstances.","is_correct":false},{"text":"Group attack","isCorrect":false,"rationale":"'Group attack' is incorrect. The correct answer is 'Attack ensuring no risk to offender from victim defense'. Treachery means employing means that ensure the commission of the crime without risk from the victim's defense. Review: Aggravating Circumstances.","is_correct":false}]$opt$::jsonb),
  ('cj_026', $opt$[{"text":"Time to reflect between decision and execution","isCorrect":true,"rationale":"Evident premeditation requires (1) determination to commit crime, (2) act showing determination, (3) sufficient time between determination and execution.","is_correct":true},{"text":"Sudden attack giving the victim no chance to defend","is_correct":false,"rationale":"That is treachery, not evident premeditation."},{"text":"Killing committed in the heat of passion","is_correct":false,"rationale":"That is passion or obfuscation, a mitigating circumstance and the opposite of cool reflection."},{"text":"Committing the crime for a price or reward","is_correct":false,"rationale":"That is the aggravating circumstance of price, reward or promise."}]$opt$::jsonb, $opt$[{"text":"Time to reflect between decision and execution","isCorrect":true,"rationale":"Evident premeditation requires (1) determination to commit crime, (2) act showing determination, (3) sufficient time between determination and execution.","is_correct":true},{"text":"Sudden impulse","isCorrect":false,"rationale":"'Sudden impulse' is incorrect. The correct answer is 'Time to reflect between decision and execution'. Evident premeditation requires (1) determination to commit crime, (2) act showing determination, (3) sufficient time between determination and execution. Review: Aggravating Circumstances.","is_correct":false},{"text":"Accident","isCorrect":false,"rationale":"'Accident' is incorrect. The correct answer is 'Time to reflect between decision and execution'. Evident premeditation requires (1) determination to commit crime, (2) act showing determination, (3) sufficient time between determination and execution. Review: Aggravating Circumstances.","is_correct":false},{"text":"Negligence","isCorrect":false,"rationale":"'Negligence' is incorrect. The correct answer is 'Time to reflect between decision and execution'. Evident premeditation requires (1) determination to commit crime, (2) act showing determination, (3) sufficient time between determination and execution. Review: Aggravating Circumstances.","is_correct":false}]$opt$::jsonb),
  ('qb_cl_006', $opt$[{"text":"Employment of means to ensure commission without risk from defense","isCorrect":true,"rationale":"Treachery (alevosia) involves employing means, methods, or forms that directly and specially ensure execution without risk to the offender from any defense the victim might make.","is_correct":true},{"text":"Commission of the crime at night in an uninhabited place","is_correct":false,"rationale":"Nighttime and uninhabited place are separate aggravating circumstances, not treachery."},{"text":"Use of superior strength out of proportion to the victim's","is_correct":false,"rationale":"That is abuse of superior strength, a different circumstance that treachery absorbs when both are present."},{"text":"Deliberate planning with sufficient time to reflect on the consequences","is_correct":false,"rationale":"That is evident premeditation, not treachery."}]$opt$::jsonb, $opt$[{"text":"Employment of means to ensure commission without risk from defense","isCorrect":true,"rationale":"Treachery (alevosia) involves employing means, methods, or forms that directly and specially ensure execution without risk to the offender from any defense the victim might make.","is_correct":true},{"text":"Use of poison","isCorrect":false,"rationale":"'Use of poison' is incorrect. The correct answer is 'Employment of means to ensure commission without risk from defense'. Treachery (alevosia) involves employing means, methods, or forms that directly and specially ensure execution without risk to the offender from any defense the victim might make. Review: Aggravating Circumstances.","is_correct":false},{"text":"Commission during nighttime","isCorrect":false,"rationale":"'Commission during nighttime' is incorrect. The correct answer is 'Employment of means to ensure commission without risk from defense'. Treachery (alevosia) involves employing means, methods, or forms that directly and specially ensure execution without risk to the offender from any defense the victim might make. Review: Aggravating Circumstances.","is_correct":false},{"text":"Presence of two or more armed persons","isCorrect":false,"rationale":"'Presence of two or more armed persons' is incorrect. The correct answer is 'Employment of means to ensure commission without risk from defense'. Treachery (alevosia) involves employing means, methods, or forms that directly and specially ensure execution without risk to the offender from any defense the victim might make. Review: Aggravating Circumstances.","is_correct":false}]$opt$::jsonb),
  ('qb_cj_010', $opt$[{"text":"By the President during invasion or rebellion","isCorrect":true,"rationale":"Under Article VII, Section 18, the President may suspend the writ of habeas corpus in cases of invasion or rebellion when public safety requires it.","is_correct":true},{"text":"By Congress during invasion or rebellion","is_correct":false,"rationale":"The power to suspend belongs to the President (Art. VII, Sec. 18). Congress may only revoke or extend the suspension."},{"text":"By the President whenever public safety requires","is_correct":false,"rationale":"Public safety alone is not enough; there must be actual invasion or rebellion AND public safety must require it."},{"text":"By the Supreme Court upon petition of the President","is_correct":false,"rationale":"The Supreme Court reviews the factual basis of a suspension; it does not suspend the writ."}]$opt$::jsonb, $opt$[{"text":"By the President during invasion or rebellion","isCorrect":true,"rationale":"Under Article VII, Section 18, the President may suspend the writ of habeas corpus in cases of invasion or rebellion when public safety requires it.","is_correct":true},{"text":"By Congress at any time","isCorrect":false,"rationale":"'By Congress at any time' is incorrect. The correct answer is 'By the President during invasion or rebellion'. Under Article VII, Section 18, the President may suspend the writ of habeas corpus in cases of invasion or rebellion when public safety requires it. Review: Constitutional Law.","is_correct":false},{"text":"By the Supreme Court","isCorrect":false,"rationale":"'By the Supreme Court' is incorrect. The correct answer is 'By the President during invasion or rebellion'. Under Article VII, Section 18, the President may suspend the writ of habeas corpus in cases of invasion or rebellion when public safety requires it. Review: Constitutional Law.","is_correct":false},{"text":"It can never be suspended","isCorrect":false,"rationale":"'It can never be suspended' is incorrect. The correct answer is 'By the President during invasion or rebellion'. Under Article VII, Section 18, the President may suspend the writ of habeas corpus in cases of invasion or rebellion when public safety requires it. Review: Constitutional Law.","is_correct":false}]$opt$::jsonb),
  ('cj_010', $opt$[{"text":"Original document must be presented","isCorrect":true,"rationale":"The best evidence rule requires that the original document be presented when its contents are the subject of inquiry.","is_correct":true},{"text":"Certified copies are always enough","is_correct":false,"rationale":"Copies are allowed only in the exceptions under Rule 130, like loss or destruction of the original. The rule requires the original."},{"text":"The most credible witness must testify","is_correct":false,"rationale":"The rule is about documents, not the credibility of witnesses."},{"text":"Physical evidence outweighs testimony","is_correct":false,"rationale":"That is a general way of weighing evidence, not the best evidence rule."}]$opt$::jsonb, $opt$[{"text":"Original document must be presented","isCorrect":true,"rationale":"The best evidence rule requires that the original document be presented when its contents are the subject of inquiry.","is_correct":true},{"text":"Witness testimony is sufficient","isCorrect":false,"rationale":"'Witness testimony is sufficient' is incorrect. The correct answer is 'Original document must be presented'. The best evidence rule requires that the original document be presented when its contents are the subject of inquiry. Review: Court Testimony.","is_correct":false},{"text":"Copies are preferred","isCorrect":false,"rationale":"'Copies are preferred' is incorrect. The correct answer is 'Original document must be presented'. The best evidence rule requires that the original document be presented when its contents are the subject of inquiry. Review: Court Testimony.","is_correct":false},{"text":"Hearsay is admissible","isCorrect":false,"rationale":"'Hearsay is admissible' is incorrect. The correct answer is 'Original document must be presented'. The best evidence rule requires that the original document be presented when its contents are the subject of inquiry. Review: Court Testimony.","is_correct":false}]$opt$::jsonb),
  ('cj_012', $opt$[{"text":"Acts wrong because prohibited by law","isCorrect":true,"rationale":"Mala prohibita are acts that are wrong only because they are prohibited by statute, like illegal parking.","is_correct":true},{"text":"Acts wrong in themselves by nature","is_correct":false,"rationale":"That is mala in se. Mala prohibita are wrong only because a law prohibits them."},{"text":"Acts punished only when done with intent","is_correct":false,"rationale":"Intent is generally immaterial in mala prohibita; doing the prohibited act is enough."},{"text":"Acts punished under the Revised Penal Code","is_correct":false,"rationale":"RPC felonies are generally mala in se; mala prohibita are mostly found in special penal laws."}]$opt$::jsonb, $opt$[{"text":"Acts wrong because prohibited by law","isCorrect":true,"rationale":"Mala prohibita are acts that are wrong only because they are prohibited by statute, like illegal parking.","is_correct":true},{"text":"Acts wrong in themselves","isCorrect":false,"rationale":"'Acts wrong in themselves' is incorrect. The correct answer is 'Acts wrong because prohibited by law'. Mala prohibita are acts that are wrong only because they are prohibited by statute, like illegal parking. Review: Criminal Law Book I.","is_correct":false},{"text":"Acts of self-defense","isCorrect":false,"rationale":"'Acts of self-defense' is incorrect. The correct answer is 'Acts wrong because prohibited by law'. Mala prohibita are acts that are wrong only because they are prohibited by statute, like illegal parking. Review: Criminal Law Book I.","is_correct":false},{"text":"Acts of passion","isCorrect":false,"rationale":"'Acts of passion' is incorrect. The correct answer is 'Acts wrong because prohibited by law'. Mala prohibita are acts that are wrong only because they are prohibited by statute, like illegal parking. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_014', $opt$[{"text":"Deceit or malice","isCorrect":true,"rationale":"Dolo refers to deceit or malice - the deliberate intent to do an unlawful act.","is_correct":true},{"text":"Fault or negligence","is_correct":false,"rationale":"That is culpa. Dolo means deliberate intent, or malice."},{"text":"Lack of foresight","is_correct":false,"rationale":"That is a form of imprudence, which belongs to culpa, not dolo."},{"text":"Accident without fault","is_correct":false,"rationale":"That is an exempting circumstance under Art. 12, not dolo."}]$opt$::jsonb, $opt$[{"text":"Deceit or malice","isCorrect":true,"rationale":"Dolo refers to deceit or malice - the deliberate intent to do an unlawful act.","is_correct":true},{"text":"Negligence","isCorrect":false,"rationale":"'Negligence' is incorrect. The correct answer is 'Deceit or malice'. Dolo refers to deceit or malice - the deliberate intent to do an unlawful act. Review: Criminal Law Book I.","is_correct":false},{"text":"Accident","isCorrect":false,"rationale":"'Accident' is incorrect. The correct answer is 'Deceit or malice'. Dolo refers to deceit or malice - the deliberate intent to do an unlawful act. Review: Criminal Law Book I.","is_correct":false},{"text":"Self-defense","isCorrect":false,"rationale":"'Self-defense' is incorrect. The correct answer is 'Deceit or malice'. Dolo refers to deceit or malice - the deliberate intent to do an unlawful act. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_015', $opt$[{"text":"Fault or negligence","isCorrect":true,"rationale":"Culpa refers to fault or negligence - lack of foresight or lack of skill.","is_correct":true},{"text":"Deceit or malice","is_correct":false,"rationale":"That is dolo, the deliberate intent to do wrong."},{"text":"Intent to commit a felony","is_correct":false,"rationale":"Intent belongs to dolo. Culpa is wrongdoing through imprudence, negligence, lack of skill or foresight."},{"text":"Accident without fault or intent","is_correct":false,"rationale":"That is an exempting circumstance; culpa still involves fault."}]$opt$::jsonb, $opt$[{"text":"Fault or negligence","isCorrect":true,"rationale":"Culpa refers to fault or negligence - lack of foresight or lack of skill.","is_correct":true},{"text":"Intentional act","isCorrect":false,"rationale":"'Intentional act' is incorrect. The correct answer is 'Fault or negligence'. Culpa refers to fault or negligence - lack of foresight or lack of skill. Review: Criminal Law Book I.","is_correct":false},{"text":"Premeditated act","isCorrect":false,"rationale":"'Premeditated act' is incorrect. The correct answer is 'Fault or negligence'. Culpa refers to fault or negligence - lack of foresight or lack of skill. Review: Criminal Law Book I.","is_correct":false},{"text":"Conspiracy","isCorrect":false,"rationale":"'Conspiracy' is incorrect. The correct answer is 'Fault or negligence'. Culpa refers to fault or negligence - lack of foresight or lack of skill. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_049', $opt$[{"text":"Agreement to commit a felony and decision to commit it","isCorrect":true,"rationale":"Conspiracy exists when two or more persons agree to commit a felony and decide to commit it.","is_correct":true},{"text":"Proposal by one person to another to commit a felony","is_correct":false,"rationale":"That is proposal. Conspiracy needs both the agreement and the decision of two or more persons."},{"text":"Cooperation in a felony by previous or simultaneous acts","is_correct":false,"rationale":"That describes accomplices (Art. 18), who cooperate without being in conspiracy."},{"text":"Concealing the effects of a felony after it was committed","is_correct":false,"rationale":"That describes accessories (Art. 19)."}]$opt$::jsonb, $opt$[{"text":"Agreement to commit a felony and decision to commit it","isCorrect":true,"rationale":"Conspiracy exists when two or more persons agree to commit a felony and decide to commit it.","is_correct":true},{"text":"Solo planning","isCorrect":false,"rationale":"'Solo planning' is incorrect. The correct answer is 'Agreement to commit a felony and decision to commit it'. Conspiracy exists when two or more persons agree to commit a felony and decide to commit it. Review: Criminal Law Book I.","is_correct":false},{"text":"Negligent act","isCorrect":false,"rationale":"'Negligent act' is incorrect. The correct answer is 'Agreement to commit a felony and decision to commit it'. Conspiracy exists when two or more persons agree to commit a felony and decide to commit it. Review: Criminal Law Book I.","is_correct":false},{"text":"Accident","isCorrect":false,"rationale":"'Accident' is incorrect. The correct answer is 'Agreement to commit a felony and decision to commit it'. Conspiracy exists when two or more persons agree to commit a felony and decide to commit it. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_050', $opt$[{"text":"Act of one is act of all","isCorrect":true,"rationale":"In conspiracy, the act of one conspirator is the act of all - all are equally liable.","is_correct":true},{"text":"Only the mastermind is liable","is_correct":false,"rationale":"In conspiracy all conspirators are equally liable, whatever their part."},{"text":"Each is liable for their own acts only","is_correct":false,"rationale":"That is the rule without conspiracy. With conspiracy, the act of one is the act of all."},{"text":"Penalty is lowered by one degree","is_correct":false,"rationale":"Conspiracy does not lower the penalty. It is accomplices who get one degree lower."}]$opt$::jsonb, $opt$[{"text":"Act of one is act of all","isCorrect":true,"rationale":"In conspiracy, the act of one conspirator is the act of all - all are equally liable.","is_correct":true},{"text":"Only mastermind liable","isCorrect":false,"rationale":"'Only mastermind liable' is incorrect. The correct answer is 'Act of one is act of all'. In conspiracy, the act of one conspirator is the act of all - all are equally liable. Review: Criminal Law Book I.","is_correct":false},{"text":"Each liable for own acts only","isCorrect":false,"rationale":"'Each liable for own acts only' is incorrect. The correct answer is 'Act of one is act of all'. In conspiracy, the act of one conspirator is the act of all - all are equally liable. Review: Criminal Law Book I.","is_correct":false},{"text":"No liability","isCorrect":false,"rationale":"'No liability' is incorrect. The correct answer is 'Act of one is act of all'. In conspiracy, the act of one conspirator is the act of all - all are equally liable. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_086', $opt$[{"text":"Agreement to commit a crime","isCorrect":true,"rationale":"Conspiracy exists when two or more persons agree to commit a crime and decide to commit it.","is_correct":true},{"text":"Proposal to commit a crime","is_correct":false,"rationale":"Proposal is made by one person; conspiracy needs the agreement of two or more."},{"text":"Cooperation after the crime is committed","is_correct":false,"rationale":"That describes accessories, not conspirators."},{"text":"Mere presence at the scene of the crime","is_correct":false,"rationale":"Mere presence, without agreement, does not make one a conspirator."}]$opt$::jsonb, $opt$[{"text":"Agreement to commit a crime","isCorrect":true,"rationale":"Conspiracy exists when two or more persons agree to commit a crime and decide to commit it.","is_correct":true},{"text":"Solo criminal act","isCorrect":false,"rationale":"'Solo criminal act' is incorrect. The correct answer is 'Agreement to commit a crime'. Conspiracy exists when two or more persons agree to commit a crime and decide to commit it. Review: Criminal Law Book I.","is_correct":false},{"text":"Accidental crime","isCorrect":false,"rationale":"'Accidental crime' is incorrect. The correct answer is 'Agreement to commit a crime'. Conspiracy exists when two or more persons agree to commit a crime and decide to commit it. Review: Criminal Law Book I.","is_correct":false},{"text":"Self-defense","isCorrect":false,"rationale":"'Self-defense' is incorrect. The correct answer is 'Agreement to commit a crime'. Conspiracy exists when two or more persons agree to commit a crime and decide to commit it. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_087', $opt$[{"text":"Proposing to another to commit a crime","isCorrect":true,"rationale":"Proposal is when a person proposes to another the commission of a crime.","is_correct":true},{"text":"Agreeing with another to commit a crime","is_correct":false,"rationale":"That is conspiracy. Proposal is when one who has decided to commit a felony proposes it to others."},{"text":"Beginning the crime by overt acts","is_correct":false,"rationale":"That is the attempted stage."},{"text":"Planning a crime alone without telling anyone","is_correct":false,"rationale":"Planning alone is not punishable; proposal needs another person."}]$opt$::jsonb, $opt$[{"text":"Proposing to another to commit a crime","isCorrect":true,"rationale":"Proposal is when a person proposes to another the commission of a crime.","is_correct":true},{"text":"Planning alone","isCorrect":false,"rationale":"'Planning alone' is incorrect. The correct answer is 'Proposing to another to commit a crime'. Proposal is when a person proposes to another the commission of a crime. Review: Criminal Law Book I.","is_correct":false},{"text":"Attempted crime","isCorrect":false,"rationale":"'Attempted crime' is incorrect. The correct answer is 'Proposing to another to commit a crime'. Proposal is when a person proposes to another the commission of a crime. Review: Criminal Law Book I.","is_correct":false},{"text":"Frustrated crime","isCorrect":false,"rationale":"'Frustrated crime' is incorrect. The correct answer is 'Proposing to another to commit a crime'. Proposal is when a person proposes to another the commission of a crime. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_094', $opt$[{"text":"May be mitigating or aggravating","isCorrect":true,"rationale":"Alternative circumstances may be mitigating or aggravating depending on the case.","is_correct":true},{"text":"May be justifying or exempting","is_correct":false,"rationale":"Alternative circumstances affect the penalty only as mitigating or aggravating; they never justify or exempt."},{"text":"Always aggravate the penalty","is_correct":false,"rationale":"They aggravate only in some cases, depending on the nature and effects of the crime."},{"text":"Always lower the penalty by one degree","is_correct":false,"rationale":"That describes privileged mitigating circumstances. Alternative circumstances may mitigate or aggravate."}]$opt$::jsonb, $opt$[{"text":"May be mitigating or aggravating","isCorrect":true,"rationale":"Alternative circumstances may be mitigating or aggravating depending on the case.","is_correct":true},{"text":"Always mitigating","isCorrect":false,"rationale":"'Always mitigating' is incorrect. The correct answer is 'May be mitigating or aggravating'. Alternative circumstances may be mitigating or aggravating depending on the case. Review: Criminal Law Book I.","is_correct":false},{"text":"Always aggravating","isCorrect":false,"rationale":"'Always aggravating' is incorrect. The correct answer is 'May be mitigating or aggravating'. Alternative circumstances may be mitigating or aggravating depending on the case. Review: Criminal Law Book I.","is_correct":false},{"text":"Neither","isCorrect":false,"rationale":"'Neither' is incorrect. The correct answer is 'May be mitigating or aggravating'. Alternative circumstances may be mitigating or aggravating depending on the case. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_095', $opt$[{"text":"Alternative circumstance","isCorrect":true,"rationale":"Intoxication is an alternative circumstance - mitigating if not habitual or intentional.","is_correct":true},{"text":"Mitigating circumstance only","is_correct":false,"rationale":"Intoxication mitigates only when it is not habitual or intentional; when habitual or intentional it aggravates. That makes it alternative."},{"text":"Aggravating circumstance only","is_correct":false,"rationale":"Intoxication aggravates only when habitual or intentional; otherwise it mitigates."},{"text":"Exempting circumstance","is_correct":false,"rationale":"Intoxication never exempts; at most it mitigates."}]$opt$::jsonb, $opt$[{"text":"Alternative circumstance","isCorrect":true,"rationale":"Intoxication is an alternative circumstance - mitigating if not habitual or intentional.","is_correct":true},{"text":"Always mitigating","isCorrect":false,"rationale":"'Always mitigating' is incorrect. The correct answer is 'Alternative circumstance'. Intoxication is an alternative circumstance - mitigating if not habitual or intentional. Review: Criminal Law Book I.","is_correct":false},{"text":"Always aggravating","isCorrect":false,"rationale":"'Always aggravating' is incorrect. The correct answer is 'Alternative circumstance'. Intoxication is an alternative circumstance - mitigating if not habitual or intentional. Review: Criminal Law Book I.","is_correct":false},{"text":"Always exempting","isCorrect":false,"rationale":"'Always exempting' is incorrect. The correct answer is 'Alternative circumstance'. Intoxication is an alternative circumstance - mitigating if not habitual or intentional. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb),
  ('cj_004', $opt$[{"text":"Reclusion Perpetua to Death","isCorrect":true,"rationale":"Murder is punishable by Reclusion Perpetua to Death under Article 248 of the RPC.","is_correct":true},{"text":"Reclusion Temporal","is_correct":false,"rationale":"That is the penalty for homicide (Art. 249)."},{"text":"Prision Mayor to Reclusion Temporal","is_correct":false,"rationale":"That range is too low; murder is punished by reclusion perpetua to death under Art. 248."},{"text":"Life Imprisonment to Death","is_correct":false,"rationale":"Life imprisonment is the term used in special laws, not the RPC; the RPC penalty is reclusion perpetua."}]$opt$::jsonb, $opt$[{"text":"Reclusion Perpetua to Death","isCorrect":true,"rationale":"Murder is punishable by Reclusion Perpetua to Death under Article 248 of the RPC.","is_correct":true},{"text":"Reclusion Temporal","isCorrect":false,"rationale":"'Reclusion Temporal' is incorrect. The correct answer is 'Reclusion Perpetua to Death'. Murder is punishable by Reclusion Perpetua to Death under Article 248 of the RPC. Review: Criminal Law Book II.","is_correct":false},{"text":"Prision Mayor","isCorrect":false,"rationale":"'Prision Mayor' is incorrect. The correct answer is 'Reclusion Perpetua to Death'. Murder is punishable by Reclusion Perpetua to Death under Article 248 of the RPC. Review: Criminal Law Book II.","is_correct":false},{"text":"Life Imprisonment","isCorrect":false,"rationale":"'Life Imprisonment' is incorrect. The correct answer is 'Reclusion Perpetua to Death'. Murder is punishable by Reclusion Perpetua to Death under Article 248 of the RPC. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_028', $opt$[{"text":"Presence of qualifying circumstances","isCorrect":true,"rationale":"Murder is homicide with qualifying circumstances like treachery, evident premeditation, or cruelty.","is_correct":true},{"text":"Presence of mitigating circumstances","is_correct":false,"rationale":"Mitigating circumstances lower the penalty within a crime; qualifying circumstances change homicide into murder."},{"text":"Relationship between offender and victim","is_correct":false,"rationale":"Relationship makes the killing parricide, not murder."},{"text":"Number of wounds inflicted","is_correct":false,"rationale":"The number of wounds does not decide the crime; qualifying circumstances do."}]$opt$::jsonb, $opt$[{"text":"Presence of qualifying circumstances","isCorrect":true,"rationale":"Murder is homicide with qualifying circumstances like treachery, evident premeditation, or cruelty.","is_correct":true},{"text":"Type of weapon used","isCorrect":false,"rationale":"'Type of weapon used' is incorrect. The correct answer is 'Presence of qualifying circumstances'. Murder is homicide with qualifying circumstances like treachery, evident premeditation, or cruelty. Review: Criminal Law Book II.","is_correct":false},{"text":"Number of victims","isCorrect":false,"rationale":"'Number of victims' is incorrect. The correct answer is 'Presence of qualifying circumstances'. Murder is homicide with qualifying circumstances like treachery, evident premeditation, or cruelty. Review: Criminal Law Book II.","is_correct":false},{"text":"Location of crime","isCorrect":false,"rationale":"'Location of crime' is incorrect. The correct answer is 'Presence of qualifying circumstances'. Murder is homicide with qualifying circumstances like treachery, evident premeditation, or cruelty. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_031', $opt$[{"text":"When attended by qualifying circumstances","isCorrect":true,"rationale":"Homicide becomes murder when attended by qualifying circumstances like treachery, evident premeditation, etc.","is_correct":true},{"text":"When attended by generic aggravating circumstances","is_correct":false,"rationale":"Generic aggravating circumstances raise the penalty within homicide but do not turn it into murder."},{"text":"When the victim is the offender's spouse","is_correct":false,"rationale":"That makes the killing parricide."},{"text":"When multiple wounds are inflicted","is_correct":false,"rationale":"The number of wounds alone does not make homicide murder."}]$opt$::jsonb, $opt$[{"text":"When attended by qualifying circumstances","isCorrect":true,"rationale":"Homicide becomes murder when attended by qualifying circumstances like treachery, evident premeditation, etc.","is_correct":true},{"text":"When weapon is used","isCorrect":false,"rationale":"'When weapon is used' is incorrect. The correct answer is 'When attended by qualifying circumstances'. Homicide becomes murder when attended by qualifying circumstances like treachery, evident premeditation, etc. Review: Criminal Law Book II.","is_correct":false},{"text":"When victim dies instantly","isCorrect":false,"rationale":"'When victim dies instantly' is incorrect. The correct answer is 'When attended by qualifying circumstances'. Homicide becomes murder when attended by qualifying circumstances like treachery, evident premeditation, etc. Review: Criminal Law Book II.","is_correct":false},{"text":"When multiple wounds inflicted","isCorrect":false,"rationale":"'When multiple wounds inflicted' is incorrect. The correct answer is 'When attended by qualifying circumstances'. Homicide becomes murder when attended by qualifying circumstances like treachery, evident premeditation, etc. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_032', $opt$[{"text":"Homicide committed by reason or on occasion of robbery","isCorrect":true,"rationale":"Robbery with homicide is a special complex crime where killing occurs by reason or on occasion of robbery.","is_correct":true},{"text":"Robbery and homicide charged as two separate crimes","is_correct":false,"rationale":"Robbery with homicide is a single special complex crime, not two separate crimes."},{"text":"Homicide committed first, with robbery as an afterthought","is_correct":false,"rationale":"If the intent to take property came only after the killing, there are separate crimes, not robbery with homicide."},{"text":"Killing of a person during a kidnapping","is_correct":false,"rationale":"That is kidnapping with homicide, a different special complex crime."}]$opt$::jsonb, $opt$[{"text":"Homicide committed by reason or on occasion of robbery","isCorrect":true,"rationale":"Robbery with homicide is a special complex crime where killing occurs by reason or on occasion of robbery.","is_correct":true},{"text":"Separate crimes of robbery and homicide","isCorrect":false,"rationale":"'Separate crimes of robbery and homicide' is incorrect. The correct answer is 'Homicide committed by reason or on occasion of robbery'. Robbery with homicide is a special complex crime where killing occurs by reason or on occasion of robbery. Review: Criminal Law Book II.","is_correct":false},{"text":"Robbery only","isCorrect":false,"rationale":"'Robbery only' is incorrect. The correct answer is 'Homicide committed by reason or on occasion of robbery'. Robbery with homicide is a special complex crime where killing occurs by reason or on occasion of robbery. Review: Criminal Law Book II.","is_correct":false},{"text":"Homicide only","isCorrect":false,"rationale":"'Homicide only' is incorrect. The correct answer is 'Homicide committed by reason or on occasion of robbery'. Robbery with homicide is a special complex crime where killing occurs by reason or on occasion of robbery. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_035', $opt$[{"text":"Theft by domestic servant or with grave abuse of trust","isCorrect":true,"rationale":"Qualified theft is committed by a domestic servant, or with grave abuse of confidence, or involving motor vehicles.","is_correct":true},{"text":"Theft committed with violence against persons","is_correct":false,"rationale":"Violence or intimidation makes it robbery, not theft."},{"text":"Theft committed by a public officer of public funds","is_correct":false,"rationale":"That is malversation (Art. 217)."},{"text":"Taking property through deceit that causes damage to the owner","is_correct":false,"rationale":"That is estafa (Art. 315)."}]$opt$::jsonb, $opt$[{"text":"Theft by domestic servant or with grave abuse of trust","isCorrect":true,"rationale":"Qualified theft is committed by a domestic servant, or with grave abuse of confidence, or involving motor vehicles.","is_correct":true},{"text":"Simple theft","isCorrect":false,"rationale":"'Simple theft' is incorrect. The correct answer is 'Theft by domestic servant or with grave abuse of trust'. Qualified theft is committed by a domestic servant, or with grave abuse of confidence, or involving motor vehicles. Review: Criminal Law Book II.","is_correct":false},{"text":"Robbery","isCorrect":false,"rationale":"'Robbery' is incorrect. The correct answer is 'Theft by domestic servant or with grave abuse of trust'. Qualified theft is committed by a domestic servant, or with grave abuse of confidence, or involving motor vehicles. Review: Criminal Law Book II.","is_correct":false},{"text":"Carnapping","isCorrect":false,"rationale":"'Carnapping' is incorrect. The correct answer is 'Theft by domestic servant or with grave abuse of trust'. Qualified theft is committed by a domestic servant, or with grave abuse of confidence, or involving motor vehicles. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_046', $opt$[{"text":"Sexual assault through force, threat, or intimidation","isCorrect":true,"rationale":"Rape includes sexual assault through force, threat, intimidation, or when victim is deprived of reason.","is_correct":true},{"text":"Crime against chastity requiring a private complaint","is_correct":false,"rationale":"RA 8353 reclassified rape as a crime against persons, so it no longer needs a private complaint."},{"text":"Carnal knowledge of a woman only, never of a man","is_correct":false,"rationale":"RA 8353 added rape by sexual assault, which can be committed against any person, including men."},{"text":"Unjust vexation of a sexual nature","is_correct":false,"rationale":"Unjust vexation is a light felony; rape involves carnal knowledge or sexual assault through force, threat or intimidation."}]$opt$::jsonb, $opt$[{"text":"Sexual assault through force, threat, or intimidation","isCorrect":true,"rationale":"Rape includes sexual assault through force, threat, intimidation, or when victim is deprived of reason.","is_correct":true},{"text":"Only forcible intercourse","isCorrect":false,"rationale":"'Only forcible intercourse' is incorrect. The correct answer is 'Sexual assault through force, threat, or intimidation'. Rape includes sexual assault through force, threat, intimidation, or when victim is deprived of reason. Review: Criminal Law Book II.","is_correct":false},{"text":"Only against women","isCorrect":false,"rationale":"'Only against women' is incorrect. The correct answer is 'Sexual assault through force, threat, or intimidation'. Rape includes sexual assault through force, threat, intimidation, or when victim is deprived of reason. Review: Criminal Law Book II.","is_correct":false},{"text":"Property crime","isCorrect":false,"rationale":"'Property crime' is incorrect. The correct answer is 'Sexual assault through force, threat, or intimidation'. Rape includes sexual assault through force, threat, intimidation, or when victim is deprived of reason. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_056', $opt$[{"text":"Prision Mayor","isCorrect":true,"rationale":"Serious physical injuries are punishable by Prision Mayor under Article 263 of the RPC.","is_correct":true},{"text":"Reclusion temporal","is_correct":false,"rationale":"Art. 263 does not reach reclusion temporal; its highest penalty is prision mayor."},{"text":"Arresto menor","is_correct":false,"rationale":"Arresto menor is for slight physical injuries (Art. 266)."},{"text":"Destierro","is_correct":false,"rationale":"Destierro is banishment, not a penalty for physical injuries under Art. 263."}]$opt$::jsonb, $opt$[{"text":"Prision Mayor","isCorrect":true,"rationale":"Serious physical injuries are punishable by Prision Mayor under Article 263 of the RPC.","is_correct":true},{"text":"Prision Correccional","isCorrect":false,"rationale":"'Prision Correccional' is incorrect. The correct answer is 'Prision Mayor'. Serious physical injuries are punishable by Prision Mayor under Article 263 of the RPC. Review: Criminal Law Book II.","is_correct":false},{"text":"Arresto Mayor","isCorrect":false,"rationale":"'Arresto Mayor' is incorrect. The correct answer is 'Prision Mayor'. Serious physical injuries are punishable by Prision Mayor under Article 263 of the RPC. Review: Criminal Law Book II.","is_correct":false},{"text":"Arresto Menor","isCorrect":false,"rationale":"'Arresto Menor' is incorrect. The correct answer is 'Prision Mayor'. Serious physical injuries are punishable by Prision Mayor under Article 263 of the RPC. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_057', $opt$[{"text":"Attack on person in authority while performing duties","isCorrect":true,"rationale":"Direct assault is attacking or using force on a person in authority or agent while performing official duties.","is_correct":true},{"text":"Refusal to obey a lawful order of a person in authority","is_correct":false,"rationale":"That is resistance and disobedience (Art. 151)."},{"text":"Rising publicly to prevent officials from performing duties","is_correct":false,"rationale":"That is sedition (Art. 139)."},{"text":"Attack on a private person in a public place","is_correct":false,"rationale":"The victim of direct assault must be a person in authority or an agent of one."}]$opt$::jsonb, $opt$[{"text":"Attack on person in authority while performing duties","isCorrect":true,"rationale":"Direct assault is attacking or using force on a person in authority or agent while performing official duties.","is_correct":true},{"text":"Simple assault","isCorrect":false,"rationale":"'Simple assault' is incorrect. The correct answer is 'Attack on person in authority while performing duties'. Direct assault is attacking or using force on a person in authority or agent while performing official duties. Review: Criminal Law Book II.","is_correct":false},{"text":"Robbery","isCorrect":false,"rationale":"'Robbery' is incorrect. The correct answer is 'Attack on person in authority while performing duties'. Direct assault is attacking or using force on a person in authority or agent while performing official duties. Review: Criminal Law Book II.","is_correct":false},{"text":"Homicide","isCorrect":false,"rationale":"'Homicide' is incorrect. The correct answer is 'Attack on person in authority while performing duties'. Direct assault is attacking or using force on a person in authority or agent while performing official duties. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_058', $opt$[{"text":"Refusing to obey lawful orders of authority","isCorrect":true,"rationale":"Resistance and disobedience is refusing to obey the lawful orders of a person in authority.","is_correct":true},{"text":"Attacking a person in authority on duty","is_correct":false,"rationale":"That is direct assault, which involves force or serious intimidation."},{"text":"Rising publicly to overthrow the government","is_correct":false,"rationale":"That is rebellion."},{"text":"Attacking someone who helps a person in authority","is_correct":false,"rationale":"That is indirect assault (Art. 149)."}]$opt$::jsonb, $opt$[{"text":"Refusing to obey lawful orders of authority","isCorrect":true,"rationale":"Resistance and disobedience is refusing to obey the lawful orders of a person in authority.","is_correct":true},{"text":"Direct assault","isCorrect":false,"rationale":"'Direct assault' is incorrect. The correct answer is 'Refusing to obey lawful orders of authority'. Resistance and disobedience is refusing to obey the lawful orders of a person in authority. Review: Criminal Law Book II.","is_correct":false},{"text":"Sedition","isCorrect":false,"rationale":"'Sedition' is incorrect. The correct answer is 'Refusing to obey lawful orders of authority'. Resistance and disobedience is refusing to obey the lawful orders of a person in authority. Review: Criminal Law Book II.","is_correct":false},{"text":"Rebellion","isCorrect":false,"rationale":"'Rebellion' is incorrect. The correct answer is 'Refusing to obey lawful orders of authority'. Resistance and disobedience is refusing to obey the lawful orders of a person in authority. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_088', $opt$[{"text":"Crime against persons","isCorrect":true,"rationale":"Under RA 8353, rape is reclassified as a crime against persons, not chastity.","is_correct":true},{"text":"Crime against property","is_correct":false,"rationale":"Rape is not a property crime; RA 8353 classifies it as a crime against persons."},{"text":"Crime against public order","is_correct":false,"rationale":"Crimes against public order include rebellion and sedition, not rape."},{"text":"Crime against chastity","is_correct":false,"rationale":"Before RA 8353 rape was a crime against chastity; the law reclassified it as a crime against persons."}]$opt$::jsonb, $opt$[{"text":"Crime against persons","isCorrect":true,"rationale":"Under RA 8353, rape is reclassified as a crime against persons, not chastity.","is_correct":true},{"text":"Crime against property","isCorrect":false,"rationale":"'Crime against property' is incorrect. The correct answer is 'Crime against persons'. Under RA 8353, rape is reclassified as a crime against persons, not chastity. Review: Criminal Law Book II.","is_correct":false},{"text":"Crime against public order","isCorrect":false,"rationale":"'Crime against public order' is incorrect. The correct answer is 'Crime against persons'. Under RA 8353, rape is reclassified as a crime against persons, not chastity. Review: Criminal Law Book II.","is_correct":false},{"text":"Crime against morals","isCorrect":false,"rationale":"'Crime against morals' is incorrect. The correct answer is 'Crime against persons'. Under RA 8353, rape is reclassified as a crime against persons, not chastity. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_089', $opt$[{"text":"Prision correccional to prision mayor","isCorrect":true,"rationale":"Robbery with force upon things is punishable by prision correccional to prision mayor.","is_correct":true},{"text":"Reclusion perpetua to death","is_correct":false,"rationale":"That range is for the gravest crimes, like murder or robbery with homicide."},{"text":"Fine only, without imprisonment","is_correct":false,"rationale":"Robbery always carries imprisonment; a fine alone is never its penalty."},{"text":"Arresto menor or public censure","is_correct":false,"rationale":"Those are light penalties for light felonies; robbery is a grave or less grave felony."}]$opt$::jsonb, $opt$[{"text":"Prision correccional to prision mayor","isCorrect":true,"rationale":"Robbery with force upon things is punishable by prision correccional to prision mayor.","is_correct":true},{"text":"Death penalty","isCorrect":false,"rationale":"'Death penalty' is incorrect. The correct answer is 'Prision correccional to prision mayor'. Robbery with force upon things is punishable by prision correccional to prision mayor. Review: Criminal Law Book II.","is_correct":false},{"text":"Fine only","isCorrect":false,"rationale":"'Fine only' is incorrect. The correct answer is 'Prision correccional to prision mayor'. Robbery with force upon things is punishable by prision correccional to prision mayor. Review: Criminal Law Book II.","is_correct":false},{"text":"Reclusion perpetua","isCorrect":false,"rationale":"'Reclusion perpetua' is incorrect. The correct answer is 'Prision correccional to prision mayor'. Robbery with force upon things is punishable by prision correccional to prision mayor. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_126', $opt$[{"text":"Presence of qualifying circumstances","isCorrect":true,"rationale":"Murder requires the presence of qualifying circumstances like treachery, evident premeditation, etc.","is_correct":true},{"text":"Presence of generic aggravating circumstances","is_correct":false,"rationale":"Generic aggravating circumstances raise the penalty but do not turn homicide into murder."},{"text":"Intent to kill the victim","is_correct":false,"rationale":"Intent to kill is present in both homicide and murder."},{"text":"Kind of weapon that was used","is_correct":false,"rationale":"The weapon does not decide the crime; qualifying circumstances do."}]$opt$::jsonb, $opt$[{"text":"Presence of qualifying circumstances","isCorrect":true,"rationale":"Murder requires the presence of qualifying circumstances like treachery, evident premeditation, etc.","is_correct":true},{"text":"Weapon used","isCorrect":false,"rationale":"'Weapon used' is incorrect. The correct answer is 'Presence of qualifying circumstances'. Murder requires the presence of qualifying circumstances like treachery, evident premeditation, etc. Review: Criminal Law Book II.","is_correct":false},{"text":"Number of victims","isCorrect":false,"rationale":"'Number of victims' is incorrect. The correct answer is 'Presence of qualifying circumstances'. Murder requires the presence of qualifying circumstances like treachery, evident premeditation, etc. Review: Criminal Law Book II.","is_correct":false},{"text":"Location of crime","isCorrect":false,"rationale":"'Location of crime' is incorrect. The correct answer is 'Presence of qualifying circumstances'. Murder requires the presence of qualifying circumstances like treachery, evident premeditation, etc. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_128', $opt$[{"text":"Killing of a child less than 3 days old","isCorrect":true,"rationale":"Infanticide is the killing of a child less than three days old by the mother or maternal grandparents.","is_correct":true},{"text":"Killing of a child less than 7 days old","is_correct":false,"rationale":"The law sets three days (72 hours); an older child's killing is parricide or murder, not infanticide."},{"text":"Killing of a fetus inside the mother's womb","is_correct":false,"rationale":"That is abortion (Arts. 256-259)."},{"text":"Killing of one's own legitimate child of any age","is_correct":false,"rationale":"That is parricide (Art. 246)."}]$opt$::jsonb, $opt$[{"text":"Killing of a child less than 3 days old","isCorrect":true,"rationale":"Infanticide is the killing of a child less than three days old by the mother or maternal grandparents.","is_correct":true},{"text":"Killing of any child","isCorrect":false,"rationale":"'Killing of any child' is incorrect. The correct answer is 'Killing of a child less than 3 days old'. Infanticide is the killing of a child less than three days old by the mother or maternal grandparents. Review: Criminal Law Book II.","is_correct":false},{"text":"Killing of infant in womb","isCorrect":false,"rationale":"'Killing of infant in womb' is incorrect. The correct answer is 'Killing of a child less than 3 days old'. Infanticide is the killing of a child less than three days old by the mother or maternal grandparents. Review: Criminal Law Book II.","is_correct":false},{"text":"Child abuse","isCorrect":false,"rationale":"'Child abuse' is incorrect. The correct answer is 'Killing of a child less than 3 days old'. Infanticide is the killing of a child less than three days old by the mother or maternal grandparents. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb),
  ('cj_038', $opt$[{"text":"Before conviction for non-capital offenses","isCorrect":true,"rationale":"Bail is a matter of right before conviction for offenses not punishable by death, reclusion perpetua, or life imprisonment.","is_correct":true},{"text":"After conviction by the RTC for any offense","is_correct":false,"rationale":"After conviction by the RTC, bail becomes discretionary, not a matter of right."},{"text":"Before conviction for offenses punished by reclusion perpetua","is_correct":false,"rationale":"For these, bail is not a right when evidence of guilt is strong; it is decided after a hearing."},{"text":"Only when the prosecutor agrees","is_correct":false,"rationale":"Bail as a right does not depend on the prosecutor's consent."}]$opt$::jsonb, $opt$[{"text":"Before conviction for non-capital offenses","isCorrect":true,"rationale":"Bail is a matter of right before conviction for offenses not punishable by death, reclusion perpetua, or life imprisonment.","is_correct":true},{"text":"Always","isCorrect":false,"rationale":"'Always' is incorrect. The correct answer is 'Before conviction for non-capital offenses'. Bail is a matter of right before conviction for offenses not punishable by death, reclusion perpetua, or life imprisonment. Review: Criminal Procedure.","is_correct":false},{"text":"Never","isCorrect":false,"rationale":"'Never' is incorrect. The correct answer is 'Before conviction for non-capital offenses'. Bail is a matter of right before conviction for offenses not punishable by death, reclusion perpetua, or life imprisonment. Review: Criminal Procedure.","is_correct":false},{"text":"Only after conviction","isCorrect":false,"rationale":"'Only after conviction' is incorrect. The correct answer is 'Before conviction for non-capital offenses'. Bail is a matter of right before conviction for offenses not punishable by death, reclusion perpetua, or life imprisonment. Review: Criminal Procedure.","is_correct":false}]$opt$::jsonb),
  ('cj_040', $opt$[{"text":"Allowed only under specific circumstances in Rule 113","isCorrect":true,"rationale":"Warrantless arrests are allowed: (1) in flagrante delicto, (2) hot pursuit, (3) escaped prisoner.","is_correct":true},{"text":"Allowed whenever the officer has reasonable suspicion","is_correct":false,"rationale":"Mere suspicion is not enough; Rule 113, Sec. 5 lists specific cases such as in flagrante, hot pursuit and escapees."},{"text":"Allowed only for crimes punishable by over 6 years","is_correct":false,"rationale":"Rule 113 does not depend on the penalty; it depends on the circumstances of the arrest."},{"text":"Never allowed without prior court approval","is_correct":false,"rationale":"Rule 113, Sec. 5 allows arrests without a warrant in specific cases."}]$opt$::jsonb, $opt$[{"text":"Allowed only under specific circumstances in Rule 113","isCorrect":true,"rationale":"Warrantless arrests are allowed: (1) in flagrante delicto, (2) hot pursuit, (3) escaped prisoner.","is_correct":true},{"text":"Always allowed","isCorrect":false,"rationale":"'Always allowed' is incorrect. The correct answer is 'Allowed only under specific circumstances in Rule 113'. Warrantless arrests are allowed: (1) in flagrante delicto, (2) hot pursuit, (3) escaped prisoner. Review: Criminal Procedure.","is_correct":false},{"text":"Never allowed","isCorrect":false,"rationale":"'Never allowed' is incorrect. The correct answer is 'Allowed only under specific circumstances in Rule 113'. Warrantless arrests are allowed: (1) in flagrante delicto, (2) hot pursuit, (3) escaped prisoner. Review: Criminal Procedure.","is_correct":false},{"text":"Only for felonies","isCorrect":false,"rationale":"'Only for felonies' is incorrect. The correct answer is 'Allowed only under specific circumstances in Rule 113'. Warrantless arrests are allowed: (1) in flagrante delicto, (2) hot pursuit, (3) escaped prisoner. Review: Criminal Procedure.","is_correct":false}]$opt$::jsonb),
  ('cj_090', $opt$[{"text":"Sworn statement by offended party","isCorrect":true,"rationale":"A complaint is a sworn written statement charging a person with an offense.","is_correct":true},{"text":"Accusation in writing filed by the prosecutor","is_correct":false,"rationale":"That is an information, not a complaint."},{"text":"Unsworn report written by a police officer","is_correct":false,"rationale":"A complaint must be sworn. A police report is not a complaint."},{"text":"Order of the court directing an arrest","is_correct":false,"rationale":"That is a warrant of arrest."}]$opt$::jsonb, $opt$[{"text":"Sworn statement by offended party","isCorrect":true,"rationale":"A complaint is a sworn written statement charging a person with an offense.","is_correct":true},{"text":"Court decision","isCorrect":false,"rationale":"'Court decision' is incorrect. The correct answer is 'Sworn statement by offended party'. A complaint is a sworn written statement charging a person with an offense. Review: Criminal Procedure.","is_correct":false},{"text":"Police report","isCorrect":false,"rationale":"'Police report' is incorrect. The correct answer is 'Sworn statement by offended party'. A complaint is a sworn written statement charging a person with an offense. Review: Criminal Procedure.","is_correct":false},{"text":"Prosecutor motion","isCorrect":false,"rationale":"'Prosecutor motion' is incorrect. The correct answer is 'Sworn statement by offended party'. A complaint is a sworn written statement charging a person with an offense. Review: Criminal Procedure.","is_correct":false}]$opt$::jsonb),
  ('cj_091', $opt$[{"text":"Accusation filed by prosecutor","isCorrect":true,"rationale":"An information is an accusation in writing filed by the prosecutor.","is_correct":true},{"text":"Sworn accusation by the offended party","is_correct":false,"rationale":"That is a complaint, not an information."},{"text":"Order issued by the court for arrest","is_correct":false,"rationale":"That is a warrant of arrest."},{"text":"Motion filed by the defense to dismiss","is_correct":false,"rationale":"That is a motion to quash or to dismiss."}]$opt$::jsonb, $opt$[{"text":"Accusation filed by prosecutor","isCorrect":true,"rationale":"An information is an accusation in writing filed by the prosecutor.","is_correct":true},{"text":"Private complaint","isCorrect":false,"rationale":"'Private complaint' is incorrect. The correct answer is 'Accusation filed by prosecutor'. An information is an accusation in writing filed by the prosecutor. Review: Criminal Procedure.","is_correct":false},{"text":"Court order","isCorrect":false,"rationale":"'Court order' is incorrect. The correct answer is 'Accusation filed by prosecutor'. An information is an accusation in writing filed by the prosecutor. Review: Criminal Procedure.","is_correct":false},{"text":"Defense motion","isCorrect":false,"rationale":"'Defense motion' is incorrect. The correct answer is 'Accusation filed by prosecutor'. An information is an accusation in writing filed by the prosecutor. Review: Criminal Procedure.","is_correct":false}]$opt$::jsonb),
  ('cj_130', $opt$[{"text":"No person shall be tried twice for the same offense","isCorrect":true,"rationale":"Double jeopardy prohibits trying a person twice for the same offense after acquittal or conviction.","is_correct":true},{"text":"No person shall be compelled to testify against oneself","is_correct":false,"rationale":"That is the right against self-incrimination."},{"text":"No person shall be detained without charges","is_correct":false,"rationale":"That is protection against arbitrary detention (Art. 125 RPC)."},{"text":"No person shall be punished by a law passed after the act","is_correct":false,"rationale":"That is the ex post facto prohibition."}]$opt$::jsonb, $opt$[{"text":"No person shall be tried twice for the same offense","isCorrect":true,"rationale":"Double jeopardy prohibits trying a person twice for the same offense after acquittal or conviction.","is_correct":true},{"text":"Trial can be repeated","isCorrect":false,"rationale":"'Trial can be repeated' is incorrect. The correct answer is 'No person shall be tried twice for the same offense'. Double jeopardy prohibits trying a person twice for the same offense after acquittal or conviction. Review: Criminal Procedure.","is_correct":false},{"text":"Appeals are prohibited","isCorrect":false,"rationale":"'Appeals are prohibited' is incorrect. The correct answer is 'No person shall be tried twice for the same offense'. Double jeopardy prohibits trying a person twice for the same offense after acquittal or conviction. Review: Criminal Procedure.","is_correct":false},{"text":"Only one witness allowed","isCorrect":false,"rationale":"'Only one witness allowed' is incorrect. The correct answer is 'No person shall be tried twice for the same offense'. Double jeopardy prohibits trying a person twice for the same offense after acquittal or conviction. Review: Criminal Procedure.","is_correct":false}]$opt$::jsonb),
  ('qb_cj_003', $opt$[{"text":"Procedural and Administrative","is_correct":false,"rationale":"Administrative due process is a setting, not an aspect; the two aspects are substantive and procedural."},{"text":"Substantive and Procedural","isCorrect":true,"rationale":"Due process has two aspects: substantive (the law itself must be fair) and procedural (fair procedure in applying the law).","is_correct":true},{"text":"Substantive and Equitable","is_correct":false,"rationale":"Equitable is not an aspect of due process; the second aspect is procedural."},{"text":"Criminal and Civil","is_correct":false,"rationale":"Those are kinds of cases, not aspects of due process."}]$opt$::jsonb, $opt$[{"text":"Criminal and Civil","isCorrect":false,"rationale":"'Criminal and Civil' is incorrect. The correct answer is 'Substantive and Procedural'. Due process has two aspects: substantive (the law itself must be fair) and procedural (fair procedure in applying the law). Review: Due Process.","is_correct":false},{"text":"Substantive and Procedural","isCorrect":true,"rationale":"Due process has two aspects: substantive (the law itself must be fair) and procedural (fair procedure in applying the law).","is_correct":true},{"text":"Legal and Equitable","isCorrect":false,"rationale":"'Legal and Equitable' is incorrect. The correct answer is 'Substantive and Procedural'. Due process has two aspects: substantive (the law itself must be fair) and procedural (fair procedure in applying the law). Review: Due Process.","is_correct":false},{"text":"Public and Private","isCorrect":false,"rationale":"'Public and Private' is incorrect. The correct answer is 'Substantive and Procedural'. Due process has two aspects: substantive (the law itself must be fair) and procedural (fair procedure in applying the law). Review: Due Process.","is_correct":false}]$opt$::jsonb),
  ('cj_022', $opt$[{"text":"No criminal liability but civil liability remains","isCorrect":true,"rationale":"Exempting circumstances remove criminal liability but civil liability may still exist.","is_correct":true},{"text":"The act is lawful, so there is neither crime nor liability","is_correct":false,"rationale":"That describes justifying circumstances, where the act itself is lawful. With exempting circumstances there is a crime but no criminal liability."},{"text":"Criminal liability but no civil liability","is_correct":false,"rationale":"It is the reverse: the offender is exempt from criminal liability, but civil liability generally remains (Art. 101)."},{"text":"Penalty is lowered by one or two degrees","is_correct":false,"rationale":"That is the effect of privileged mitigating circumstances."}]$opt$::jsonb, $opt$[{"text":"No criminal liability but civil liability remains","isCorrect":true,"rationale":"Exempting circumstances remove criminal liability but civil liability may still exist.","is_correct":true},{"text":"No criminal and civil liability","isCorrect":false,"rationale":"'No criminal and civil liability' is incorrect. The correct answer is 'No criminal liability but civil liability remains'. Exempting circumstances remove criminal liability but civil liability may still exist. Review: Exempting Circumstances.","is_correct":false},{"text":"Reduced penalty","isCorrect":false,"rationale":"'Reduced penalty' is incorrect. The correct answer is 'No criminal liability but civil liability remains'. Exempting circumstances remove criminal liability but civil liability may still exist. Review: Exempting Circumstances.","is_correct":false},{"text":"Increased penalty","isCorrect":false,"rationale":"'Increased penalty' is incorrect. The correct answer is 'No criminal liability but civil liability remains'. Exempting circumstances remove criminal liability but civil liability may still exist. Review: Exempting Circumstances.","is_correct":false}]$opt$::jsonb),
  ('cj_021', $opt$[{"text":"Defender not induced by revenge or resentment","isCorrect":true,"rationale":"For defense of stranger, the defender must not be induced by revenge, resentment, or other evil motive.","is_correct":true},{"text":"Defender is related to the person attacked","is_correct":false,"rationale":"Relationship is required for defense of relatives, not of strangers."},{"text":"Defender used the least harmful means available to stop the attack","is_correct":false,"rationale":"Reasonable necessity of the means is shared by all three defenses; it is not the additional element for strangers."},{"text":"Defender acted under orders of a superior","is_correct":false,"rationale":"That is obedience to a superior order, a separate justifying circumstance."}]$opt$::jsonb, $opt$[{"text":"Defender not induced by revenge or resentment","isCorrect":true,"rationale":"For defense of stranger, the defender must not be induced by revenge, resentment, or other evil motive.","is_correct":true},{"text":"Blood relationship","isCorrect":false,"rationale":"'Blood relationship' is incorrect. The correct answer is 'Defender not induced by revenge or resentment'. For defense of stranger, the defender must not be induced by revenge, resentment, or other evil motive. Review: Justifying Circumstances.","is_correct":false},{"text":"Employment relationship","isCorrect":false,"rationale":"'Employment relationship' is incorrect. The correct answer is 'Defender not induced by revenge or resentment'. For defense of stranger, the defender must not be induced by revenge, resentment, or other evil motive. Review: Justifying Circumstances.","is_correct":false},{"text":"Friendship","isCorrect":false,"rationale":"'Friendship' is incorrect. The correct answer is 'Defender not induced by revenge or resentment'. For defense of stranger, the defender must not be induced by revenge, resentment, or other evil motive. Review: Justifying Circumstances.","is_correct":false}]$opt$::jsonb),
  ('qb_cl_003', $opt$[{"text":"Unlawful aggression, reasonable necessity, lack of sufficient provocation","isCorrect":true,"rationale":"The three elements are: unlawful aggression, reasonable necessity of the means employed, and lack of sufficient provocation on the part of the person defending himself.","is_correct":true},{"text":"Unlawful aggression, reasonable necessity, and the aggressor being a stranger","is_correct":false,"rationale":"The relationship to the aggressor does not matter in self-defense; the third element is lack of sufficient provocation by the defender."},{"text":"Unlawful aggression, proportionate weapon, lack of sufficient provocation","is_correct":false,"rationale":"The law does not require equal weapons; it asks whether the means used was reasonably necessary."},{"text":"Intent, motive, and opportunity to commit the act","is_correct":false,"rationale":"Those are investigative concepts, not the elements of self-defense."}]$opt$::jsonb, $opt$[{"text":"Unlawful aggression, reasonable necessity, lack of sufficient provocation","isCorrect":true,"rationale":"The three elements are: unlawful aggression, reasonable necessity of the means employed, and lack of sufficient provocation on the part of the person defending himself.","is_correct":true},{"text":"Intent, motive, opportunity","isCorrect":false,"rationale":"'Intent, motive, opportunity' is incorrect. The correct answer is 'Unlawful aggression, reasonable necessity, lack of sufficient provocation'. The three elements are: unlawful aggression, reasonable necessity of the means employed, and lack of sufficient provocation on the part of the person defending himself. Review: Justifying Circumstances.","is_correct":false},{"text":"Premeditation, treachery, evident premeditation","isCorrect":false,"rationale":"'Premeditation, treachery, evident premeditation' is incorrect. The correct answer is 'Unlawful aggression, reasonable necessity, lack of sufficient provocation'. The three elements are: unlawful aggression, reasonable necessity of the means employed, and lack of sufficient provocation on the part of the person defending himself. Review: Justifying Circumstances.","is_correct":false},{"text":"Minority, insanity, imbecility","isCorrect":false,"rationale":"'Minority, insanity, imbecility' is incorrect. The correct answer is 'Unlawful aggression, reasonable necessity, lack of sufficient provocation'. The three elements are: unlawful aggression, reasonable necessity of the means employed, and lack of sufficient provocation on the part of the person defending himself. Review: Justifying Circumstances.","is_correct":false}]$opt$::jsonb),
  ('qb_cj_009', $opt$[{"text":"Crime is a free choice weighed against pleasure and pain","is_correct":false,"rationale":"That is the classical school (Beccaria, Bentham)."},{"text":"Crime is caused by factors beyond individual control","isCorrect":true,"rationale":"Positivist criminology, founded by Lombroso, Ferri, and Garofalo, holds that criminal behavior is determined by biological, psychological, and social factors.","is_correct":true},{"text":"Punishment should fit the crime, not the offender","is_correct":false,"rationale":"That is classical thinking; positivists individualize treatment to the offender."},{"text":"Crime is caused by possession by evil spirits","is_correct":false,"rationale":"That is demonological thinking, which came before scientific criminology."}]$opt$::jsonb, $opt$[{"text":"Criminals exercise free will","isCorrect":false,"rationale":"'Criminals exercise free will' is incorrect. The correct answer is 'Crime is caused by factors beyond individual control'. Positivist criminology, founded by Lombroso, Ferri, and Garofalo, holds that criminal behavior is determined by biological, psychological, and social factors. Review: Legal Philosophy.","is_correct":false},{"text":"Crime is caused by factors beyond individual control","isCorrect":true,"rationale":"Positivist criminology, founded by Lombroso, Ferri, and Garofalo, holds that criminal behavior is determined by biological, psychological, and social factors.","is_correct":true},{"text":"Punishment should be severe","isCorrect":false,"rationale":"'Punishment should be severe' is incorrect. The correct answer is 'Crime is caused by factors beyond individual control'. Positivist criminology, founded by Lombroso, Ferri, and Garofalo, holds that criminal behavior is determined by biological, psychological, and social factors. Review: Legal Philosophy.","is_correct":false},{"text":"All crimes deserve death penalty","isCorrect":false,"rationale":"'All crimes deserve death penalty' is incorrect. The correct answer is 'Crime is caused by factors beyond individual control'. Positivist criminology, founded by Lombroso, Ferri, and Garofalo, holds that criminal behavior is determined by biological, psychological, and social factors. Review: Legal Philosophy.","is_correct":false}]$opt$::jsonb),
  ('qb_cl_008', $opt$[{"text":"Presence of mitigating circumstances like voluntary surrender","is_correct":false,"rationale":"Mitigating circumstances lower the penalty within a crime; they do not separate murder from homicide."},{"text":"Presence of qualifying circumstances like treachery","isCorrect":true,"rationale":"Murder is homicide attended by qualifying circumstances such as treachery, evident premeditation, or cruelty.","is_correct":true},{"text":"Relationship of the offender to the victim, like a spouse","is_correct":false,"rationale":"Relationship makes the killing parricide."},{"text":"Use of a deadly weapon such as a firearm","is_correct":false,"rationale":"The kind of weapon used does not turn homicide into murder."}]$opt$::jsonb, $opt$[{"text":"The weapon used","isCorrect":false,"rationale":"'The weapon used' is incorrect. The correct answer is 'Presence of qualifying circumstances like treachery'. Murder is homicide attended by qualifying circumstances such as treachery, evident premeditation, or cruelty. Review: Revised Penal Code Book 2.","is_correct":false},{"text":"Presence of qualifying circumstances like treachery","isCorrect":true,"rationale":"Murder is homicide attended by qualifying circumstances such as treachery, evident premeditation, or cruelty.","is_correct":true},{"text":"The number of victims","isCorrect":false,"rationale":"'The number of victims' is incorrect. The correct answer is 'Presence of qualifying circumstances like treachery'. Murder is homicide attended by qualifying circumstances such as treachery, evident premeditation, or cruelty. Review: Revised Penal Code Book 2.","is_correct":false},{"text":"The location of the crime","isCorrect":false,"rationale":"'The location of the crime' is incorrect. The correct answer is 'Presence of qualifying circumstances like treachery'. Murder is homicide attended by qualifying circumstances such as treachery, evident premeditation, or cruelty. Review: Revised Penal Code Book 2.","is_correct":false}]$opt$::jsonb),
  ('qb_cj_006', $opt$[{"text":"The person is named in a police blotter entry as a suspect in a crime committed several days earlier","is_correct":false,"rationale":"Rule 113 requires personal knowledge of a crime that has just been committed; a blotter entry about an older crime is not enough."},{"text":"The person is committing, has just committed, or is about to commit a crime in the presence of the arresting officer","isCorrect":true,"rationale":"Under Rule 113, Section 5, warrantless arrests are valid for in flagrante delicto, hot pursuit, and escaped prisoners.","is_correct":true},{"text":"The arresting officer received an anonymous tip that the person is carrying illegal drugs in a bag","is_correct":false,"rationale":"An anonymous tip alone is not enough; the officer must personally see an overt act or have personal knowledge."},{"text":"The person matches the general description of a suspect in a robbery that was committed in another city last month","is_correct":false,"rationale":"A general description and an old crime elsewhere do not meet Rule 113, Sec. 5; a warrant is needed."}]$opt$::jsonb, $opt$[{"text":"The person is suspected of any crime","isCorrect":false,"rationale":"'The person is suspected of any crime' is incorrect. The correct answer is 'The person is committing, has just committed, or is about to commit a crime in the presence of the arresting officer'. Under Rule 113, Section 5, warrantless arrests are valid for in flagrante delicto, hot pursuit, and escaped prisoners. Review: Rules of Court.","is_correct":false},{"text":"The person is committing, has just committed, or is about to commit a crime in the presence of the arresting officer","isCorrect":true,"rationale":"Under Rule 113, Section 5, warrantless arrests are valid for in flagrante delicto, hot pursuit, and escaped prisoners.","is_correct":true},{"text":"The arresting officer has a personal grudge","isCorrect":false,"rationale":"'The arresting officer has a personal grudge' is incorrect. The correct answer is 'The person is committing, has just committed, or is about to commit a crime in the presence of the arresting officer'. Under Rule 113, Section 5, warrantless arrests are valid for in flagrante delicto, hot pursuit, and escaped prisoners. Review: Rules of Court.","is_correct":false},{"text":"The crime was committed last month","isCorrect":false,"rationale":"'The crime was committed last month' is incorrect. The correct answer is 'The person is committing, has just committed, or is about to commit a crime in the presence of the arresting officer'. Under Rule 113, Section 5, warrantless arrests are valid for in flagrante delicto, hot pursuit, and escaped prisoners. Review: Rules of Court.","is_correct":false}]$opt$::jsonb),
  ('cj_045', $opt$[{"text":"Body of the crime - proof crime was committed","isCorrect":true,"rationale":"Corpus delicti is the body of the crime - proof that a crime has actually been committed.","is_correct":true},{"text":"The body of the deceased victim","is_correct":false,"rationale":"Corpus delicti means the body of the crime, the fact that a crime was committed, not the corpse."},{"text":"Extrajudicial confession of the accused","is_correct":false,"rationale":"A confession alone is not enough to convict without proof of the corpus delicti."},{"text":"Proof of the identity of the person who committed the crime","is_correct":false,"rationale":"The identity of the offender must also be proved, but it is separate from corpus delicti."}]$opt$::jsonb, $opt$[{"text":"Body of the crime - proof crime was committed","isCorrect":true,"rationale":"Corpus delicti is the body of the crime - proof that a crime has actually been committed.","is_correct":true},{"text":"Dead body","isCorrect":false,"rationale":"'Dead body' is incorrect. The correct answer is 'Body of the crime - proof crime was committed'. Corpus delicti is the body of the crime - proof that a crime has actually been committed. Review: Rules of Evidence.","is_correct":false},{"text":"Murder weapon","isCorrect":false,"rationale":"'Murder weapon' is incorrect. The correct answer is 'Body of the crime - proof crime was committed'. Corpus delicti is the body of the crime - proof that a crime has actually been committed. Review: Rules of Evidence.","is_correct":false},{"text":"Confession","isCorrect":false,"rationale":"'Confession' is incorrect. The correct answer is 'Body of the crime - proof crime was committed'. Corpus delicti is the body of the crime - proof that a crime has actually been committed. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb),
  ('cj_092', $opt$[{"text":"Inadmissible as fruit of poisonous tree","isCorrect":true,"rationale":"Evidence obtained illegally is inadmissible under the exclusionary rule.","is_correct":true},{"text":"Admissible if relevant to the case","is_correct":false,"rationale":"Relevance does not cure illegality; the Constitution (Art. III, Sec. 3) excludes such evidence."},{"text":"Admissible but the officer is penalized","is_correct":false,"rationale":"The Philippines applies the exclusionary rule, not just penalties for the officer."},{"text":"Admissible once the case reaches trial","is_correct":false,"rationale":"Illegally obtained evidence stays inadmissible at every stage."}]$opt$::jsonb, $opt$[{"text":"Inadmissible as fruit of poisonous tree","isCorrect":true,"rationale":"Evidence obtained illegally is inadmissible under the exclusionary rule.","is_correct":true},{"text":"Always admissible","isCorrect":false,"rationale":"'Always admissible' is incorrect. The correct answer is 'Inadmissible as fruit of poisonous tree'. Evidence obtained illegally is inadmissible under the exclusionary rule. Review: Rules of Evidence.","is_correct":false},{"text":"Admissible with penalty","isCorrect":false,"rationale":"'Admissible with penalty' is incorrect. The correct answer is 'Inadmissible as fruit of poisonous tree'. Evidence obtained illegally is inadmissible under the exclusionary rule. Review: Rules of Evidence.","is_correct":false},{"text":"Judge decides","isCorrect":false,"rationale":"'Judge decides' is incorrect. The correct answer is 'Inadmissible as fruit of poisonous tree'. Evidence obtained illegally is inadmissible under the exclusionary rule. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb),
  ('cj_093', $opt$[{"text":"Spontaneous statements during event","isCorrect":true,"rationale":"Res gestae are spontaneous statements made during or immediately after an event.","is_correct":true},{"text":"Statements made believing death is imminent","is_correct":false,"rationale":"That is a dying declaration."},{"text":"Statements against one's own interest","is_correct":false,"rationale":"That is a declaration against interest."},{"text":"Opinions given by an expert witness","is_correct":false,"rationale":"That is expert testimony, not res gestae."}]$opt$::jsonb, $opt$[{"text":"Spontaneous statements during event","isCorrect":true,"rationale":"Res gestae are spontaneous statements made during or immediately after an event.","is_correct":true},{"text":"Written confession","isCorrect":false,"rationale":"'Written confession' is incorrect. The correct answer is 'Spontaneous statements during event'. Res gestae are spontaneous statements made during or immediately after an event. Review: Rules of Evidence.","is_correct":false},{"text":"Expert testimony","isCorrect":false,"rationale":"'Expert testimony' is incorrect. The correct answer is 'Spontaneous statements during event'. Res gestae are spontaneous statements made during or immediately after an event. Review: Rules of Evidence.","is_correct":false},{"text":"Documentary evidence","isCorrect":false,"rationale":"'Documentary evidence' is incorrect. The correct answer is 'Spontaneous statements during event'. Res gestae are spontaneous statements made during or immediately after an event. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb),
  ('cj_131', $opt$[{"text":"Indirect proof requiring inference","isCorrect":true,"rationale":"Circumstantial evidence is indirect proof that requires inference to connect it to the crime.","is_correct":true},{"text":"Testimony of a witness who saw the crime","is_correct":false,"rationale":"That is direct evidence, which needs no inference."},{"text":"Evidence the court notices without proof","is_correct":false,"rationale":"That is judicial notice."},{"text":"Proof of the accused's past crimes","is_correct":false,"rationale":"Evidence of past crimes is generally not admissible to prove the present one; it is not what circumstantial evidence means."}]$opt$::jsonb, $opt$[{"text":"Indirect proof requiring inference","isCorrect":true,"rationale":"Circumstantial evidence is indirect proof that requires inference to connect it to the crime.","is_correct":true},{"text":"Direct eyewitness testimony","isCorrect":false,"rationale":"'Direct eyewitness testimony' is incorrect. The correct answer is 'Indirect proof requiring inference'. Circumstantial evidence is indirect proof that requires inference to connect it to the crime. Review: Rules of Evidence.","is_correct":false},{"text":"Physical evidence only","isCorrect":false,"rationale":"'Physical evidence only' is incorrect. The correct answer is 'Indirect proof requiring inference'. Circumstantial evidence is indirect proof that requires inference to connect it to the crime. Review: Rules of Evidence.","is_correct":false},{"text":"Written documents","isCorrect":false,"rationale":"'Written documents' is incorrect. The correct answer is 'Indirect proof requiring inference'. Circumstantial evidence is indirect proof that requires inference to connect it to the crime. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb),
  ('cj_132', $opt$[{"text":"Out of court statements are generally inadmissible","isCorrect":true,"rationale":"The hearsay rule excludes out-of-court statements offered to prove the truth of the matter asserted.","is_correct":true},{"text":"Out of court statements are always admissible if relevant","is_correct":false,"rationale":"Relevance does not cure hearsay; such statements are generally excluded unless an exception applies."},{"text":"Only statements written and signed are admissible","is_correct":false,"rationale":"The rule is about out-of-court statements offered for their truth, written or not."},{"text":"Statements made by the accused are never admissible","is_correct":false,"rationale":"Admissions and confessions of the accused can be admitted; they are not barred by the hearsay rule."}]$opt$::jsonb, $opt$[{"text":"Out of court statements are generally inadmissible","isCorrect":true,"rationale":"The hearsay rule excludes out-of-court statements offered to prove the truth of the matter asserted.","is_correct":true},{"text":"All statements are admissible","isCorrect":false,"rationale":"'All statements are admissible' is incorrect. The correct answer is 'Out of court statements are generally inadmissible'. The hearsay rule excludes out-of-court statements offered to prove the truth of the matter asserted. Review: Rules of Evidence.","is_correct":false},{"text":"Only written statements allowed","isCorrect":false,"rationale":"'Only written statements allowed' is incorrect. The correct answer is 'Out of court statements are generally inadmissible'. The hearsay rule excludes out-of-court statements offered to prove the truth of the matter asserted. Review: Rules of Evidence.","is_correct":false},{"text":"Witness must be present","isCorrect":false,"rationale":"'Witness must be present' is incorrect. The correct answer is 'Out of court statements are generally inadmissible'. The hearsay rule excludes out-of-court statements offered to prove the truth of the matter asserted. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb),
  ('qb_cl_012', $opt$[{"text":"Physical harm causing bodily injury","is_correct":false,"rationale":"That is physical violence under RA 9262."},{"text":"Forcing the woman to watch obscene material","is_correct":false,"rationale":"That is sexual violence under RA 9262."},{"text":"Intimidation, harassment, and emotional abuse","isCorrect":true,"rationale":"RA 9262 (VAWC) includes psychological violence such as intimidation, harassment, stalking, and emotional abuse.","is_correct":true},{"text":"Depriving the woman of financial support legally due her","is_correct":false,"rationale":"That is economic abuse under RA 9262."}]$opt$::jsonb, $opt$[{"text":"Physical harm only","isCorrect":false,"rationale":"'Physical harm only' is incorrect. The correct answer is 'Intimidation, harassment, and emotional abuse'. RA 9262 (VAWC) includes psychological violence such as intimidation, harassment, stalking, and emotional abuse. Review: Special Penal Laws.","is_correct":false},{"text":"Marital rape only","isCorrect":false,"rationale":"'Marital rape only' is incorrect. The correct answer is 'Intimidation, harassment, and emotional abuse'. RA 9262 (VAWC) includes psychological violence such as intimidation, harassment, stalking, and emotional abuse. Review: Special Penal Laws.","is_correct":false},{"text":"Intimidation, harassment, and emotional abuse","isCorrect":true,"rationale":"RA 9262 (VAWC) includes psychological violence such as intimidation, harassment, stalking, and emotional abuse.","is_correct":true},{"text":"Property damage only","isCorrect":false,"rationale":"'Property damage only' is incorrect. The correct answer is 'Intimidation, harassment, and emotional abuse'. RA 9262 (VAWC) includes psychological violence such as intimidation, harassment, stalking, and emotional abuse. Review: Special Penal Laws.","is_correct":false}]$opt$::jsonb),
  ('qb_crim_008', $opt$[{"text":"First-time property offenders","is_correct":false,"rationale":"Profiling works best when an offender leaves repeated behavioral patterns, as in serial crimes."},{"text":"Serial offenders","isCorrect":true,"rationale":"Criminal profiling is most effective in cases involving serial crimes where behavioral patterns can be analyzed.","is_correct":true},{"text":"Crimes with a confessed suspect","is_correct":false,"rationale":"If the offender is already known, there is nothing left to profile."},{"text":"Organized corporate fraud","is_correct":false,"rationale":"Profiling reads behavior left at crime scenes, typical of serial violent crimes, not paper fraud."}]$opt$::jsonb, $opt$[{"text":"Property crimes","isCorrect":false,"rationale":"'Property crimes' is incorrect. The correct answer is 'Serial offenders'. Criminal profiling is most effective in cases involving serial crimes where behavioral patterns can be analyzed. Review: Criminal Profiling.","is_correct":false},{"text":"Serial offenders","isCorrect":true,"rationale":"Criminal profiling is most effective in cases involving serial crimes where behavioral patterns can be analyzed.","is_correct":true},{"text":"Traffic violations","isCorrect":false,"rationale":"'Traffic violations' is incorrect. The correct answer is 'Serial offenders'. Criminal profiling is most effective in cases involving serial crimes where behavioral patterns can be analyzed. Review: Criminal Profiling.","is_correct":false},{"text":"Civil disputes","isCorrect":false,"rationale":"'Civil disputes' is incorrect. The correct answer is 'Serial offenders'. Criminal profiling is most effective in cases involving serial crimes where behavioral patterns can be analyzed. Review: Criminal Profiling.","is_correct":false}]$opt$::jsonb),
  ('cr_095', $opt$[{"text":"Blood, saliva, hair, skin cells","isCorrect":true,"rationale":"DNA can be extracted from blood, saliva, hair roots, skin cells, and other tissues.","is_correct":true},{"text":"Blood only, from fresh stains","is_correct":false,"rationale":"DNA can also come from saliva, hair roots and skin cells, not only blood."},{"text":"Saliva and blood only","is_correct":false,"rationale":"Hair with roots and skin cells also provide DNA."},{"text":"Bone and teeth only","is_correct":false,"rationale":"Bones and teeth do provide DNA, but so do blood, saliva, hair and skin cells."}]$opt$::jsonb, $opt$[{"text":"Blood, saliva, hair, skin cells","isCorrect":true,"rationale":"DNA can be extracted from blood, saliva, hair roots, skin cells, and other tissues.","is_correct":true},{"text":"Only blood","isCorrect":false,"rationale":"'Only blood' is incorrect. The correct answer is 'Blood, saliva, hair, skin cells'. DNA can be extracted from blood, saliva, hair roots, skin cells, and other tissues. Review: DNA Analysis.","is_correct":false},{"text":"Only saliva","isCorrect":false,"rationale":"'Only saliva' is incorrect. The correct answer is 'Blood, saliva, hair, skin cells'. DNA can be extracted from blood, saliva, hair roots, skin cells, and other tissues. Review: DNA Analysis.","is_correct":false},{"text":"Only hair","isCorrect":false,"rationale":"'Only hair' is incorrect. The correct answer is 'Blood, saliva, hair, skin cells'. DNA can be extracted from blood, saliva, hair roots, skin cells, and other tissues. Review: DNA Analysis.","is_correct":false}]$opt$::jsonb),
  ('cr_125', $opt$[{"text":"Blood, saliva, hair, skin cells","isCorrect":true,"rationale":"DNA can be extracted from various biological materials including blood, saliva, and hair.","is_correct":true},{"text":"Only blood and other body fluids","is_correct":false,"rationale":"Hair roots, skin cells, bones and teeth also contain DNA."},{"text":"Only cells taken from living persons","is_correct":false,"rationale":"DNA is also recovered from the dead, including bones and teeth."},{"text":"Only hair that was pulled out by the root","is_correct":false,"rationale":"Hair roots are one source, but so are blood, saliva and skin cells."}]$opt$::jsonb, $opt$[{"text":"Blood, saliva, hair, skin cells","isCorrect":true,"rationale":"DNA can be extracted from various biological materials including blood, saliva, and hair.","is_correct":true},{"text":"Only blood","isCorrect":false,"rationale":"'Only blood' is incorrect. The correct answer is 'Blood, saliva, hair, skin cells'. DNA can be extracted from various biological materials including blood, saliva, and hair. Review: DNA Analysis.","is_correct":false},{"text":"Only saliva","isCorrect":false,"rationale":"'Only saliva' is incorrect. The correct answer is 'Blood, saliva, hair, skin cells'. DNA can be extracted from various biological materials including blood, saliva, and hair. Review: DNA Analysis.","is_correct":false},{"text":"Only hair","isCorrect":false,"rationale":"'Only hair' is incorrect. The correct answer is 'Blood, saliva, hair, skin cells'. DNA can be extracted from various biological materials including blood, saliva, and hair. Review: DNA Analysis.","is_correct":false}]$opt$::jsonb),
  ('crim_137', $opt$[{"text":"Creating genetic fingerprint for identification","isCorrect":true,"rationale":"DNA profiling creates a unique genetic fingerprint that can identify individuals.","is_correct":true},{"text":"Determining a person's ABO blood group","is_correct":false,"rationale":"That is blood typing, which only places a person in a broad group."},{"text":"Comparing ridge patterns on fingers","is_correct":false,"rationale":"That is fingerprint identification (dactyloscopy)."},{"text":"Mapping every gene in a person's genome for research","is_correct":false,"rationale":"That is genome sequencing; profiling compares a few highly variable markers to identify a person."}]$opt$::jsonb, $opt$[{"text":"Creating genetic fingerprint for identification","isCorrect":true,"rationale":"DNA profiling creates a unique genetic fingerprint that can identify individuals.","is_correct":true},{"text":"Blood typing","isCorrect":false,"rationale":"'Blood typing' is incorrect. The correct answer is 'Creating genetic fingerprint for identification'. DNA profiling creates a unique genetic fingerprint that can identify individuals. Review: DNA Analysis.","is_correct":false},{"text":"Fingerprinting","isCorrect":false,"rationale":"'Fingerprinting' is incorrect. The correct answer is 'Creating genetic fingerprint for identification'. DNA profiling creates a unique genetic fingerprint that can identify individuals. Review: DNA Analysis.","is_correct":false},{"text":"Voice analysis","isCorrect":false,"rationale":"'Voice analysis' is incorrect. The correct answer is 'Creating genetic fingerprint for identification'. DNA profiling creates a unique genetic fingerprint that can identify individuals. Review: DNA Analysis.","is_correct":false}]$opt$::jsonb),
  ('qb_fs_002', $opt$[{"text":"Restriction Fragment Length Polymorphism","is_correct":false,"rationale":"RFLP was the earlier method; STR analysis replaced it because it needs less DNA and is faster."},{"text":"Short Tandem Repeats (STR)","isCorrect":true,"rationale":"STR analysis examines specific regions of DNA that vary between individuals, providing highly accurate identification.","is_correct":true},{"text":"ABO and Rh blood group typing","is_correct":false,"rationale":"Blood typing places a person in a broad class; it cannot identify an individual."},{"text":"Mitochondrial DNA sequencing only","is_correct":false,"rationale":"mtDNA is used for degraded samples or hair shafts, but routine profiling uses STRs."}]$opt$::jsonb, $opt$[{"text":"Blood type analysis","isCorrect":false,"rationale":"'Blood type analysis' is incorrect. The correct answer is 'Short Tandem Repeats (STR)'. STR analysis examines specific regions of DNA that vary between individuals, providing highly accurate identification. Review: DNA Analysis.","is_correct":false},{"text":"Short Tandem Repeats (STR)","isCorrect":true,"rationale":"STR analysis examines specific regions of DNA that vary between individuals, providing highly accurate identification.","is_correct":true},{"text":"Fingerprint comparison","isCorrect":false,"rationale":"'Fingerprint comparison' is incorrect. The correct answer is 'Short Tandem Repeats (STR)'. STR analysis examines specific regions of DNA that vary between individuals, providing highly accurate identification. Review: DNA Analysis.","is_correct":false},{"text":"Hair color analysis","isCorrect":false,"rationale":"'Hair color analysis' is incorrect. The correct answer is 'Short Tandem Repeats (STR)'. STR analysis examines specific regions of DNA that vary between individuals, providing highly accurate identification. Review: DNA Analysis.","is_correct":false}]$opt$::jsonb),
  ('cr_010', $opt$[{"text":"Loop, Whorl, Arch","isCorrect":true,"rationale":"The three main fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%).","is_correct":true},{"text":"Loop, Whorl, Accidental","is_correct":false,"rationale":"Accidental is a type of whorl in the Henry system; the three main groups are loop, whorl and arch."},{"text":"Radial, Ulnar, Tented","is_correct":false,"rationale":"Radial and ulnar are kinds of loop, and tented is a kind of arch."},{"text":"Plain, Central pocket, Double loop","is_correct":false,"rationale":"These are types of whorl, not the three main patterns."}]$opt$::jsonb, $opt$[{"text":"Loop, Whorl, Arch","isCorrect":true,"rationale":"The three main fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%).","is_correct":true},{"text":"Circle, Square, Triangle","isCorrect":false,"rationale":"'Circle, Square, Triangle' is incorrect. The correct answer is 'Loop, Whorl, Arch'. The three main fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%). Review: Dactyloscopy.","is_correct":false},{"text":"Spiral, Linear, Curved","isCorrect":false,"rationale":"'Spiral, Linear, Curved' is incorrect. The correct answer is 'Loop, Whorl, Arch'. The three main fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%). Review: Dactyloscopy.","is_correct":false},{"text":"Plain, Tented, Mixed","isCorrect":false,"rationale":"'Plain, Tented, Mixed' is incorrect. The correct answer is 'Loop, Whorl, Arch'. The three main fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%). Review: Dactyloscopy.","is_correct":false}]$opt$::jsonb),
  ('cr_013', $opt$[{"text":"Invisible print requiring development","isCorrect":true,"rationale":"Latent prints are invisible fingerprints left by natural skin oils that require development to be seen.","is_correct":true},{"text":"Visible print left in blood or ink","is_correct":false,"rationale":"That is a patent print."},{"text":"Molded print left in soft material","is_correct":false,"rationale":"That is a plastic print."},{"text":"Print taken on a card at booking","is_correct":false,"rationale":"That is a recorded, or inked, print."}]$opt$::jsonb, $opt$[{"text":"Invisible print requiring development","isCorrect":true,"rationale":"Latent prints are invisible fingerprints left by natural skin oils that require development to be seen.","is_correct":true},{"text":"Visible print","isCorrect":false,"rationale":"'Visible print' is incorrect. The correct answer is 'Invisible print requiring development'. Latent prints are invisible fingerprints left by natural skin oils that require development to be seen. Review: Dactyloscopy.","is_correct":false},{"text":"Plastic print","isCorrect":false,"rationale":"'Plastic print' is incorrect. The correct answer is 'Invisible print requiring development'. Latent prints are invisible fingerprints left by natural skin oils that require development to be seen. Review: Dactyloscopy.","is_correct":false},{"text":"Bloody print","isCorrect":false,"rationale":"'Bloody print' is incorrect. The correct answer is 'Invisible print requiring development'. Latent prints are invisible fingerprints left by natural skin oils that require development to be seen. Review: Dactyloscopy.","is_correct":false}]$opt$::jsonb),
  ('cr_014', $opt$[{"text":"Visible print made with foreign substance","isCorrect":true,"rationale":"Patent prints are visible fingerprints made when fingers contaminated with ink, blood, or other substances touch a surface.","is_correct":true},{"text":"Invisible print that needs powder or chemicals","is_correct":false,"rationale":"That is a latent print."},{"text":"Three-dimensional impression in soft material like wax","is_correct":false,"rationale":"That is a plastic print."},{"text":"Partial print showing only part of the pattern","is_correct":false,"rationale":"A partial print can be latent, patent or plastic; patent means a visible print made with a substance."}]$opt$::jsonb, $opt$[{"text":"Visible print made with foreign substance","isCorrect":true,"rationale":"Patent prints are visible fingerprints made when fingers contaminated with ink, blood, or other substances touch a surface.","is_correct":true},{"text":"Invisible print","isCorrect":false,"rationale":"'Invisible print' is incorrect. The correct answer is 'Visible print made with foreign substance'. Patent prints are visible fingerprints made when fingers contaminated with ink, blood, or other substances touch a surface. Review: Dactyloscopy.","is_correct":false},{"text":"Print on soft surface","isCorrect":false,"rationale":"'Print on soft surface' is incorrect. The correct answer is 'Visible print made with foreign substance'. Patent prints are visible fingerprints made when fingers contaminated with ink, blood, or other substances touch a surface. Review: Dactyloscopy.","is_correct":false},{"text":"Partial print","isCorrect":false,"rationale":"'Partial print' is incorrect. The correct answer is 'Visible print made with foreign substance'. Patent prints are visible fingerprints made when fingers contaminated with ink, blood, or other substances touch a surface. Review: Dactyloscopy.","is_correct":false}]$opt$::jsonb),
  ('cr_015', $opt$[{"text":"3D impression on soft surface","isCorrect":true,"rationale":"Plastic prints are three-dimensional impressions left on soft surfaces like wax, soap, or putty.","is_correct":true},{"text":"Print visible in blood","is_correct":false,"rationale":"That is a patent print."},{"text":"Hidden print needing powder","is_correct":false,"rationale":"That is a latent print."},{"text":"Print of only a fragment","is_correct":false,"rationale":"That is a partial print; plastic means a molded 3D impression."}]$opt$::jsonb, $opt$[{"text":"3D impression on soft surface","isCorrect":true,"rationale":"Plastic prints are three-dimensional impressions left on soft surfaces like wax, soap, or putty.","is_correct":true},{"text":"Latent print","isCorrect":false,"rationale":"'Latent print' is incorrect. The correct answer is '3D impression on soft surface'. Plastic prints are three-dimensional impressions left on soft surfaces like wax, soap, or putty. Review: Dactyloscopy.","is_correct":false},{"text":"Patent print","isCorrect":false,"rationale":"'Patent print' is incorrect. The correct answer is '3D impression on soft surface'. Plastic prints are three-dimensional impressions left on soft surfaces like wax, soap, or putty. Review: Dactyloscopy.","is_correct":false},{"text":"Partial print","isCorrect":false,"rationale":"'Partial print' is incorrect. The correct answer is '3D impression on soft surface'. Plastic prints are three-dimensional impressions left on soft surfaces like wax, soap, or putty. Review: Dactyloscopy.","is_correct":false}]$opt$::jsonb),
  ('cr_016', $opt$[{"text":"White or gray powder","isCorrect":true,"rationale":"Light-colored powders like white or gray are used on dark surfaces for contrast.","is_correct":true},{"text":"Black or dark powder","is_correct":false,"rationale":"Dark powder does not contrast on dark surfaces; it is used on light ones."},{"text":"Ninhydrin solution","is_correct":false,"rationale":"Ninhydrin is a chemical for prints on paper, not a powder."},{"text":"Silver nitrate solution","is_correct":false,"rationale":"Silver nitrate is a chemical method for paper, not a powder."}]$opt$::jsonb, $opt$[{"text":"White or gray powder","isCorrect":true,"rationale":"Light-colored powders like white or gray are used on dark surfaces for contrast.","is_correct":true},{"text":"Black powder","isCorrect":false,"rationale":"'Black powder' is incorrect. The correct answer is 'White or gray powder'. Light-colored powders like white or gray are used on dark surfaces for contrast. Review: Dactyloscopy.","is_correct":false},{"text":"Red powder","isCorrect":false,"rationale":"'Red powder' is incorrect. The correct answer is 'White or gray powder'. Light-colored powders like white or gray are used on dark surfaces for contrast. Review: Dactyloscopy.","is_correct":false},{"text":"Blue powder","isCorrect":false,"rationale":"'Blue powder' is incorrect. The correct answer is 'White or gray powder'. Light-colored powders like white or gray are used on dark surfaces for contrast. Review: Dactyloscopy.","is_correct":false}]$opt$::jsonb),
  ('qb_crim_002', $opt$[{"text":"Alphonse Bertillon","is_correct":false,"rationale":"Bertillon devised anthropometry, identification by body measurements."},{"text":"Sir Edward Henry","is_correct":false,"rationale":"Henry developed the fingerprint classification system used in English-speaking countries."},{"text":"Juan Vucetich","isCorrect":true,"rationale":"Juan Vucetich of Argentina developed the first workable fingerprint classification system and is considered the Father of Fingerprint Identification.","is_correct":true},{"text":"Mathieu Orfila","is_correct":false,"rationale":"Orfila is known as the Father of Toxicology."}]$opt$::jsonb, $opt$[{"text":"Alphonse Bertillon","isCorrect":false,"rationale":"'Alphonse Bertillon' is incorrect. The correct answer is 'Juan Vucetich'. Juan Vucetich of Argentina developed the first workable fingerprint classification system and is considered the Father of Fingerprint Identification. Review: Dactyloscopy.","is_correct":false},{"text":"Sir Francis Galton","isCorrect":false,"rationale":"'Sir Francis Galton' is incorrect. The correct answer is 'Juan Vucetich'. Juan Vucetich of Argentina developed the first workable fingerprint classification system and is considered the Father of Fingerprint Identification. Review: Dactyloscopy.","is_correct":false},{"text":"Juan Vucetich","isCorrect":true,"rationale":"Juan Vucetich of Argentina developed the first workable fingerprint classification system and is considered the Father of Fingerprint Identification.","is_correct":true},{"text":"Sir Edward Henry","isCorrect":false,"rationale":"'Sir Edward Henry' is incorrect. The correct answer is 'Juan Vucetich'. Juan Vucetich of Argentina developed the first workable fingerprint classification system and is considered the Father of Fingerprint Identification. Review: Dactyloscopy.","is_correct":false}]$opt$::jsonb),
