  ('crim_theory_131', $opt$[{"text":"Act only illegal because of offender's age","isCorrect":true,"rationale":"Status offenses like truancy or curfew violations are only illegal for juveniles.","is_correct":true},{"text":"Serious crime committed by a minor","is_correct":false,"rationale":"Serious crimes are illegal at any age; status offenses apply only to minors."},{"text":"Offense punished more for adults","is_correct":false,"rationale":"Status offenses are acts that are not crimes at all for adults."},{"text":"Crime that depends on social status","is_correct":false,"rationale":"Despite the name, it is not about social class; it is about the status of being a minor."}]$opt$::jsonb, $opt$[{"text":"Act only illegal because of offender's age","isCorrect":true,"rationale":"Status offenses like truancy or curfew violations are only illegal for juveniles.","is_correct":true},{"text":"Serious felony","isCorrect":false,"rationale":"'Serious felony' is incorrect. The correct answer is 'Act only illegal because of offender's age'. Status offenses like truancy or curfew violations are only illegal for juveniles. Review: Juvenile Delinquency.","is_correct":false},{"text":"Adult crime","isCorrect":false,"rationale":"'Adult crime' is incorrect. The correct answer is 'Act only illegal because of offender's age'. Status offenses like truancy or curfew violations are only illegal for juveniles. Review: Juvenile Delinquency.","is_correct":false},{"text":"Traffic violation","isCorrect":false,"rationale":"'Traffic violation' is incorrect. The correct answer is 'Act only illegal because of offender's age'. Status offenses like truancy or curfew violations are only illegal for juveniles. Review: Juvenile Delinquency.","is_correct":false}]$opt$::jsonb),
  ('se_028', $opt$[{"text":"Alternative to formal court proceedings","isCorrect":true,"rationale":"Diversion refers to alternatives to formal prosecution for juvenile offenders.","is_correct":true},{"text":"Transfer of the child to an adult jail","is_correct":false,"rationale":"RA 9344 prohibits detaining children together with adults."},{"text":"Suspension of sentence after a guilty finding","is_correct":false,"rationale":"That is suspended sentence, which happens after a finding of guilt, not instead of court."},{"text":"Dismissal of the case with no program","is_correct":false,"rationale":"Diversion still requires a program the child must complete."}]$opt$::jsonb, $opt$[{"text":"Alternative to formal court proceedings","isCorrect":true,"rationale":"Diversion refers to alternatives to formal prosecution for juvenile offenders.","is_correct":true},{"text":"Prison sentence","isCorrect":false,"rationale":"'Prison sentence' is incorrect. The correct answer is 'Alternative to formal court proceedings'. Diversion refers to alternatives to formal prosecution for juvenile offenders. Review: Juvenile Delinquency.","is_correct":false},{"text":"Death penalty","isCorrect":false,"rationale":"'Death penalty' is incorrect. The correct answer is 'Alternative to formal court proceedings'. Diversion refers to alternatives to formal prosecution for juvenile offenders. Review: Juvenile Delinquency.","is_correct":false},{"text":"Life imprisonment","isCorrect":false,"rationale":"'Life imprisonment' is incorrect. The correct answer is 'Alternative to formal court proceedings'. Diversion refers to alternatives to formal prosecution for juvenile offenders. Review: Juvenile Delinquency.","is_correct":false}]$opt$::jsonb),
