  ('se_003', $opt$[{"text":"Law Enforcement, Prosecution, Courts, Corrections, Community","isCorrect":true,"rationale":"The 5 pillars are: Law Enforcement, Prosecution, Courts, Corrections, and Community.","is_correct":true},{"text":"Law Enforcement, Prosecution, Courts, Corrections, Legislature","is_correct":false,"rationale":"Congress makes the laws but is not a pillar; the fifth pillar is the community."},{"text":"Law Enforcement, Prosecution, Defense, Courts, Corrections","is_correct":false,"rationale":"The defense is not a separate pillar; the fifth pillar is the community."},{"text":"Investigation, Trial, Verdict, Punishment, Rehabilitation","is_correct":false,"rationale":"These are stages of a case, not the pillars."}]$opt$::jsonb, $opt$[{"text":"Law Enforcement, Prosecution, Courts, Corrections, Community","isCorrect":true,"rationale":"The 5 pillars are: Law Enforcement, Prosecution, Courts, Corrections, and Community.","is_correct":true},{"text":"Police, Lawyers, Judges, Prisons, Citizens","isCorrect":false,"rationale":"'Police, Lawyers, Judges, Prisons, Citizens' is incorrect. The correct answer is 'Law Enforcement, Prosecution, Courts, Corrections, Community'. The 5 pillars are: Law Enforcement, Prosecution, Courts, Corrections, and Community. Review: Philippine Criminal Justice System.","is_correct":false},{"text":"PNP, DOJ, SC, BUCOR, Barangay","isCorrect":false,"rationale":"'PNP, DOJ, SC, BUCOR, Barangay' is incorrect. The correct answer is 'Law Enforcement, Prosecution, Courts, Corrections, Community'. The 5 pillars are: Law Enforcement, Prosecution, Courts, Corrections, and Community. Review: Philippine Criminal Justice System.","is_correct":false},{"text":"Investigation, Trial, Verdict, Punishment, Rehabilitation","isCorrect":false,"rationale":"'Investigation, Trial, Verdict, Punishment, Rehabilitation' is incorrect. The correct answer is 'Law Enforcement, Prosecution, Courts, Corrections, Community'. The 5 pillars are: Law Enforcement, Prosecution, Courts, Corrections, and Community. Review: Philippine Criminal Justice System.","is_correct":false}]$opt$::jsonb),
  ('crm_062', $opt$[{"text":"Adherence to ethical standards","isCorrect":true,"rationale":"Professional integrity means consistently adhering to ethical standards.","is_correct":true},{"text":"Loyalty to fellow officers","is_correct":false,"rationale":"Blind loyalty can lead to covering up misconduct; integrity is adherence to ethics."},{"text":"Strict obedience to any order","is_correct":false,"rationale":"Integrity requires refusing unlawful orders."},{"text":"Popularity with the public","is_correct":false,"rationale":"Integrity is not about popularity."}]$opt$::jsonb, $opt$[{"text":"Adherence to ethical standards","isCorrect":true,"rationale":"Professional integrity means consistently adhering to ethical standards.","is_correct":true},{"text":"Breaking rules","isCorrect":false,"rationale":"'Breaking rules' is incorrect. The correct answer is 'Adherence to ethical standards'. Professional integrity means consistently adhering to ethical standards. Review: Professional Conduct and Ethical Standards.","is_correct":false},{"text":"Personal interest first","isCorrect":false,"rationale":"'Personal interest first' is incorrect. The correct answer is 'Adherence to ethical standards'. Professional integrity means consistently adhering to ethical standards. Review: Professional Conduct and Ethical Standards.","is_correct":false},{"text":"Corruption","isCorrect":false,"rationale":"'Corruption' is incorrect. The correct answer is 'Adherence to ethical standards'. Professional integrity means consistently adhering to ethical standards. Review: Professional Conduct and Ethical Standards.","is_correct":false}]$opt$::jsonb),
  ('crm_091', $opt$[{"text":"Conflict between competing moral principles","isCorrect":true,"rationale":"Ethical dilemmas involve difficult choices between competing moral principles.","is_correct":true},{"text":"Choice between obeying the law and breaking it for gain","is_correct":false,"rationale":"That is a temptation, not a dilemma, because the right answer is clear."},{"text":"Situation with only one clearly right answer","is_correct":false,"rationale":"A dilemma has no clearly right answer; both choices rest on moral principles."},{"text":"Disagreement over which rule applies to a case","is_correct":false,"rationale":"That is a legal question, not a conflict between moral principles."}]$opt$::jsonb, $opt$[{"text":"Conflict between competing moral principles","isCorrect":true,"rationale":"Ethical dilemmas involve difficult choices between competing moral principles.","is_correct":true},{"text":"Clear right answer","isCorrect":false,"rationale":"'Clear right answer' is incorrect. The correct answer is 'Conflict between competing moral principles'. Ethical dilemmas involve difficult choices between competing moral principles. Review: Professional Conduct and Ethical Standards.","is_correct":false},{"text":"No moral issues","isCorrect":false,"rationale":"'No moral issues' is incorrect. The correct answer is 'Conflict between competing moral principles'. Ethical dilemmas involve difficult choices between competing moral principles. Review: Professional Conduct and Ethical Standards.","is_correct":false},{"text":"Simple decisions","isCorrect":false,"rationale":"'Simple decisions' is incorrect. The correct answer is 'Conflict between competing moral principles'. Ethical dilemmas involve difficult choices between competing moral principles. Review: Professional Conduct and Ethical Standards.","is_correct":false}]$opt$::jsonb),
  ('se_002', $opt$[{"text":"Differential Association Theory","isCorrect":true,"rationale":"Sutherland's Differential Association Theory states that criminal behavior is learned through interaction with others.","is_correct":true},{"text":"Merton's Strain Theory","is_correct":false,"rationale":"Merton's strain theory says crime comes from blocked access to goals."},{"text":"Labeling Theory","is_correct":false,"rationale":"Labeling theory says reactions to deviance push people into more crime."},{"text":"General Theory of Crime (self-control)","is_correct":false,"rationale":"Gottfredson and Hirschi say crime comes from low self-control formed in childhood."}]$opt$::jsonb, $opt$[{"text":"Differential Association Theory","isCorrect":true,"rationale":"Sutherland's Differential Association Theory states that criminal behavior is learned through interaction with others.","is_correct":true},{"text":"Strain Theory","isCorrect":false,"rationale":"'Strain Theory' is incorrect. The correct answer is 'Differential Association Theory'. Sutherland's Differential Association Theory states that criminal behavior is learned through interaction with others. Review: Psychology of Crimes.","is_correct":false},{"text":"Labeling Theory","isCorrect":false,"rationale":"'Labeling Theory' is incorrect. The correct answer is 'Differential Association Theory'. Sutherland's Differential Association Theory states that criminal behavior is learned through interaction with others. Review: Psychology of Crimes.","is_correct":false},{"text":"Control Theory","isCorrect":false,"rationale":"'Control Theory' is incorrect. The correct answer is 'Differential Association Theory'. Sutherland's Differential Association Theory states that criminal behavior is learned through interaction with others. Review: Psychology of Crimes.","is_correct":false}]$opt$::jsonb),
